insert into public.discovery_entities (type, slug, name, tagline, location, about, tags, heat, published_at) values ('project', 'global-supply-chains', 'Global Supply Chains', 'The networks that move inputs, components, and products across borders', 'Global', 'The distributed systems of suppliers, logistics, standards, capital, and skills that make modern production possible.', ARRAY['editorial','omniv'], 90, '2026-09-20T00:00:00Z') on conflict (type, slug) do update set name=excluded.name, tagline=excluded.tagline, location=excluded.location, about=excluded.about, tags=excluded.tags, updated_at=now();
insert into public.discovery_publications (publisher_id, publisher_name, type, slug, title, summary, body, subtitle, excerpt, content, category_id, reading_time, status, seo_title, seo_description, canonical_url, sources, what_this_means, question_nobody_asks, entity_refs, related_publication_ids, tags, meta, heat, published_at) values ((select id from public.discovery_entities where type='company' and slug='omniv'), 'Omniv', 'article', '01-us-china', 'The U.S. and China Are Talking Again. What Actually Changed?', 'In September, presidents Donald Trump and Xi Jinping met at the White House amid ceremonial pageantry and the familiar list of hard questions: tariffs, chips, rare-earth minerals, Taiwan and artificial intelligence. The clearest result was…', '', 'The leaders are meeting, the trade truce has been extended, and new channels are being proposed. That is a meaningful shift from escalation—not evidence that the rivalry, or its flashpoints, has been resolved.', 'In September, presidents Donald Trump and Xi Jinping met at the White House amid ceremonial pageantry and the familiar list of hard questions: tariffs, chips, rare-earth minerals, Taiwan and artificial intelligence. The clearest result was…', '[{"type":"paragraph","text":"In September, presidents Donald Trump and Xi Jinping met at the White House amid ceremonial pageantry and the familiar list of hard questions: tariffs, chips, rare-earth minerals, Taiwan and artificial intelligence. The clearest result was not a sweeping settlement. It was more time."},{"type":"paragraph","text":"The two governments extended a fragile trade truce, first reached after tariffs had surged in 2025, until January 10, 2027, according to U.S. Treasury Secretary Scott Bessent. He said negotiators wanted time to explore a bigger agreement. Reuters reported no major breakthrough at the summit, and noted that the White House had not issued its own detailed readout of the leaders’ private exchange.[1] [2]"},{"type":"paragraph","text":"That is what “talking again” means in practice: top-level contact has become regular, and officials have reopened channels to manage disputes. But the talks have not erased the tariffs, export controls, or strategic mistrust that made the relationship dangerous in the first place."},{"type":"heading","text":"From tariff shock to a pause with an expiry date","level":2},{"type":"paragraph","text":"The current process began as crisis management. In April 2025, the United States and China escalated tariffs and retaliatory measures. At Geneva the following month, they agreed to suspend 24 percentage points of their additional tariffs for an initial 90 days, while retaining a 10-point rate, and to remove other recent tariff increases. China also agreed to suspend or remove non-tariff countermeasures imposed since April 2. The joint statement established a mechanism for further discussions; it did not settle the wider trade relationship.[3]"},{"type":"paragraph","text":"That distinction matters. A pause is not the same as cancellation. The Geneva statement set a clock and a negotiating mechanism, not a final bargain over market access, industrial policy or technology restrictions."},{"type":"paragraph","text":"After later rounds, a November 2025 package broadened the agenda. The White House said China would pause new rare-earth restrictions, issue general export licenses for several critical minerals, resume purchases of American farm goods and take steps on fentanyl precursor chemicals. The United States, in turn, said it would reduce a fentanyl-related tariff by 10 percentage points and suspend heightened reciprocal tariffs until November 10, 2026.[4] [5]"},{"type":"paragraph","text":"The details were not just diplomatic language: a U.S. executive order put the tariff suspension into effect, and specified its end date. But the terms remained temporary. In September 2026, Bessent said the arrangement had been extended another two months, to January 10, 2027. That date is a public statement by the U.S. Treasury secretary, reported by Reuters—not, at the time of publication, a new jointly published treaty or a full public implementation document.[1] [6]"},{"type":"heading","text":"More machinery, but no settled bargain","level":2},{"type":"paragraph","text":"The May 2026 Trump–Xi meeting in Beijing produced a more institutional ambition. The White House said the presidents had chartered a U.S.–China Board of Trade to manage trade in non-sensitive goods and a Board of Investment to discuss investment issues. It also announced Chinese commitments on agricultural purchases, rare-earth supply concerns and an initial order of 200 Boeing aircraft.[7]"},{"type":"paragraph","text":"Those are administration announcements, not proof that every commitment has been completed. The point of the boards, if they become operational, is to create a standing place to negotiate instead of treating each dispute as a leader-to-leader emergency. The investment forum could help surface specific obstacles; the trade board could separate lower-risk commerce from sensitive areas. But the public description leaves key questions open: what counts as “non-sensitive,” who participates, and what happens when one side believes the other has not delivered?"},{"type":"paragraph","text":"By September, both governments had reason to keep that process alive. Bessent said Beijing was meeting its 25-million-ton soybean commitment but lagging on a pledge to buy $17 billion in other agricultural goods, and U.S. officials said rare-earth deliveries were also behind. He floated possible announcements on tariff reductions for $30 billion in non-sensitive goods, financial services and agricultural purchases. These were negotiating possibilities, not concluded terms.[1]"},{"type":"paragraph","text":"That gap between announced promise and verified delivery is central. In November 2025, the White House described rare-earth general licenses as the “de facto removal” of controls and listed broad commitments. China, however, has described its export controls as lawful national-security measures, not export bans, and says eligible applications can be licensed. Neither side’s characterization alone tells a buyer how quickly a particular shipment will clear.[4] [8]"},{"type":"heading","text":"The chokepoints remain real","level":2},{"type":"paragraph","text":"The dispute is not simply about tariffs. China’s leverage includes its dominant position in processing some critical minerals used across industries. The United States has leverage through access to advanced chips, manufacturing equipment and other technologies. Both governments have shown a willingness to use restrictions as bargaining tools."},{"type":"paragraph","text":"The November package temporarily eased some pressure. China pledged to suspend an expansive new round of rare-earth controls, while Washington paused a rule that would have widened export restrictions to subsidiaries of listed companies. Such reciprocal pauses can prevent immediate supply shocks, but they do not settle the underlying security claims or reverse existing controls.[4] [5]"},{"type":"paragraph","text":"Technology is where even the new dialogue looks thin. Before the September summit, Bessent said officials had agreed to create a hotline for notifying each other about AI safety incidents. Reuters reported that China’s public response did not confirm the hotline agreement, and that analysts saw little basis for substantial cooperation while both countries were competing to lead AI development.[1] A communications channel, if it functions, can help manage an incident; it is not a shared AI rulebook."},{"type":"paragraph","text":"Fentanyl shows how a politically urgent issue can remain contested even while officials negotiate. In March 2026, U.S. and Chinese representatives publicly clashed at a United Nations drugs meeting. Washington accused Beijing of failing to stop precursor sales; China rejected the allegation and criticized the use of tariffs. Reuters reported that the U.S. Supreme Court had invalidated a 10% fentanyl-related tariff imposed under an emergency statute. That ruling changed the legal basis for one tariff, not the two governments’ disagreement over enforcement or responsibility.[9]"},{"type":"heading","text":"Taiwan is not a side issue","level":2},{"type":"paragraph","text":"Trade can be paused and restarted by executive action. Taiwan is a more consequential strategic fault line. After the September meeting, China’s official news agency reported that Xi urged the United States to oppose Taiwan independence. Reuters noted that the White House had not provided its own readout of that exchange and reported no sign Washington had changed its long-standing formulation that it does not support independence.[2]"},{"type":"paragraph","text":"This is an example of why competing readouts matter. Beijing’s account states its position; it does not establish that Washington accepted it. Nor does a summit photo establish that the two sides have narrowed their disagreement. Any shift in U.S. wording or arms policy would have implications for Taiwan and U.S. allies, but the publicly available record at publication does not show that such a shift was agreed at this meeting.[2]"}]'::jsonb, 'WORLD', 7, 'published', 'The U.S. and China Are Talking Again. What Actually Changed? | Omniv', 'In September, presidents Donald Trump and Xi Jinping met at the White House amid ceremonial pageantry and the familiar list of hard questions: tariffs, chips, rare-earth minerals, Taiwan and artificial intelligence. The clearest result was…', 'https://omniv.media/p/01-us-china', '[{"name":"reuters.com","title":"US, China agree to extend trade truce by two months, work on bigger deal, Bessent says","url":"https://www.reuters.com/world/asia-pacific/us-treasurys-bessent-chinas-he-meet-unfinished-business-before-trump-xi-summit-2026-09-23/"},{"name":"reuters.com","title":"Five takeaways from Trump''s summit with Xi in Washington","url":"https://www.reuters.com/world/china/four-takeaways-trumps-summit-with-xi-washington-2026-09-24/"},{"name":"whitehouse.gov","title":"Joint Statement on U.S.-China Economic and Trade Meeting in Geneva","url":"https://www.whitehouse.gov/briefings-statements/2025/05/joint-statement-on-u-s-china-economic-and-trade-meeting-in-geneva/"},{"name":"whitehouse.gov","title":"Fact Sheet: President Donald J. Trump Strikes Deal on Economic and Trade Relations with China","url":"https://www.whitehouse.gov/fact-sheets/2025/11/fact-sheet-president-donald-j-trump-strikes-deal-on-economic-and-trade-relations-with-china/"},{"name":"whitehouse.gov","title":"Modifying Reciprocal Tariff Rates Consistent with the Economic and Trade Arrangement Between the United States and the People''s Republic of China","url":"https://www.whitehouse.gov/presidential-actions/2025/11/modifying-reciprocal-tariff-rates-consistent-with-the-economic-and-trade-arrangement-between-the-united-states-and-the-peoples-republic-of-china/"},{"name":"reuters.com","title":"US, China agree to extend ''the Busan agreement'' until January, Bessent says","url":"https://www.reuters.com/world/china/us-china-agree-extend-the-busan-agreement-until-january-bessent-says-2026-09-23/"},{"name":"whitehouse.gov","title":"Fact Sheet: President Donald J. Trump Secures Historic Deals with China, Delivering for American Workers, Farmers, and Industry","url":"https://www.whitehouse.gov/fact-sheets/2026/05/fact-sheet-president-donald-j-trump-secures-historic-deals-with-china-delivering-for-american-workers-farmers-and-industry/"},{"name":"english.mofcom.gov.cn","title":"MOFCOM Spokesperson’s Remarks on China’s Recent Economic and Trade Policies and Measures","url":"https://english.mofcom.gov.cn/News/SpokesmansRemarks/art/2025/art_c202dcc0433d476db52b1e7f7fe53926.html"},{"name":"reuters.com","title":"US and China clash over fentanyl and tariffs at global drugs meeting","url":"https://www.reuters.com/business/healthcare-pharmaceuticals/us-china-clash-over-fentanyl-tariffs-global-drugs-meeting-2026-03-09/"}]'::jsonb, 'For businesses, a truce can be valuable without being durable. It reduces the immediate risk of another tariff spiral and gives importers, exporters and manufacturers a window to plan. But a deadline in January means supply-chain decisions still have to account for renewed duties or licensing restrictions. A license policy can also be unpredictable even when there is no formal ban. For diplomacy, steady contact is itself an outcome. It offers leaders and officials more chances to clarify intentions, test proposals and keep a dispute from escalating by accident. The two sides have scheduled or discussed meetings, established working-level processes, and kept sensitive issues on the agenda. Yet the September summit’s clearest concrete result was extending a temporary economic arrangement—not settling Taiwan, advanced technology rules, or the terms of a long-term trade relationship.[1] [2] The best description is therefore neither “breakthrough” nor “nothing changed.” The relationship moved from a tariff cliff toward managed competition. That is consequential, but reversible.', 'Can either government make a promise that the other can verify—and can domestic politics tolerate the reciprocal concessions needed to keep it? The public record is heavy on commitments and light on shared scorekeeping. The White House says China is behind on some purchases and mineral deliveries; Beijing gives its own account of export licensing and insists its measures are lawful. The trade boards could help by defining milestones, publishing progress and creating a process to resolve disputes. Until there is a clear way to check performance, each side can present the same pause as a victory while preparing for the next round of pressure. That is the test for the coming months. Not whether leaders say they want stability, but whether the institutions they announce can turn a temporary truce into terms both sides can explain—and sustain—at home.', '[{"type":"project","slug":"united-states","label":"United States"},{"type":"project","slug":"china","label":"China"},{"type":"project","slug":"taiwan","label":"Taiwan"},{"type":"project","slug":"rare-earths","label":"Rare Earths"},{"type":"project","slug":"semiconductors","label":"Semiconductors"},{"type":"project","slug":"artificial-intelligence","label":"Artificial Intelligence"},{"type":"project","slug":"global-supply-chains","label":"Global Supply Chains"}]'::jsonb, '{}'::text[], ARRAY['world', 'united states', 'china', 'taiwan', 'rare earths', 'semiconductors'], '7 min read', 90, '2026-09-26T09:00:00Z') on conflict (slug) do update set publisher_id=excluded.publisher_id, publisher_name=excluded.publisher_name, title=excluded.title, summary=excluded.summary, subtitle=excluded.subtitle, excerpt=excluded.excerpt, content=excluded.content, category_id=excluded.category_id, reading_time=excluded.reading_time, status='published', seo_title=excluded.seo_title, seo_description=excluded.seo_description, canonical_url=excluded.canonical_url, sources=excluded.sources, what_this_means=excluded.what_this_means, question_nobody_asks=excluded.question_nobody_asks, entity_refs=excluded.entity_refs, related_publication_ids=excluded.related_publication_ids, tags=excluded.tags, meta=excluded.meta, heat=excluded.heat, published_at=excluded.published_at, updated_at=now();
insert into public.discovery_publications (publisher_id, publisher_name, type, slug, title, summary, body, subtitle, excerpt, content, category_id, reading_time, status, seo_title, seo_description, canonical_url, sources, what_this_means, question_nobody_asks, entity_refs, related_publication_ids, tags, meta, heat, published_at) values ((select id from public.discovery_entities where type='company' and slug='omniv'), 'Omniv', 'article', '02-japan', 'Why Japan Matters More Than Most People Realize', 'When people talk about a crisis around Taiwan, the focus tends to land on Taiwan itself, China, and Washington. But the map tells a wider story. Japan’s southwestern islands sit near Taiwan and the East China Sea; U.S. forces operate from b…', '', 'Japan is not simply America’s dependable ally or a giant economy past its peak. It is a hinge in the strategic geography of Asia—and in the industrial networks that make modern power possible.', 'When people talk about a crisis around Taiwan, the focus tends to land on Taiwan itself, China, and Washington. But the map tells a wider story. Japan’s southwestern islands sit near Taiwan and the East China Sea; U.S. forces operate from b…', '[{"type":"paragraph","text":"When people talk about a crisis around Taiwan, the focus tends to land on Taiwan itself, China, and Washington. But the map tells a wider story. Japan’s southwestern islands sit near Taiwan and the East China Sea; U.S. forces operate from bases across Japan; and Japanese companies supply materials and precision equipment that chipmakers elsewhere depend on. A conflict or disruption in this neighborhood would not stay neatly inside national borders."},{"type":"paragraph","text":"That is the first reason Japan matters: its importance is not a single statistic or weapon system. It comes from the way geography, alliance commitments, industrial capability, and diplomacy overlap. Japan is a formidable actor, but not an unconstrained one. Its choices can shape the balance around it—and its demographic and economic realities limit how quickly it can change that balance."},{"type":"heading","text":"Geography makes Japan a front-line power, whether it seeks the role or not","level":2},{"type":"paragraph","text":"Japan is an archipelago along the western Pacific edge of Asia. Its southern islands face the East China Sea and lie close to Taiwan. That location puts Japan alongside the routes, airspace, and maritime approaches that would matter in any regional emergency. It also makes Japan directly exposed to the same military pressure that affects its neighbors."},{"type":"paragraph","text":"Japan’s own 2022 National Security Strategy describes its regional security environment as the most severe and complex since the end of World War II. That is the government’s assessment, not an independent measure of threat. The document cites military build-ups, nuclear and missile developments, pressure to change the status quo by force, cyberattacks, and disinformation, while warning that the line between peacetime and crisis is becoming less clear. It specifically connects Russia’s invasion of Ukraine to concern about possible future crises in the Indo-Pacific. [1]"},{"type":"paragraph","text":"The geography has practical consequences. In February 2025, the U.S. and Japanese leaders said they intended to increase their forces’ presence in Japan’s Southwest Islands, improve command coordination, and expand joint training. The statement reaffirmed that the U.S.-Japan treaty’s Article V applies to the Senkaku Islands, which Japan administers and China also claims as the Diaoyu Islands. That is a description of the leaders’ position and treaty commitment—not proof that a conflict is inevitable. [2]"},{"type":"paragraph","text":"Japan’s role is therefore not simply to host American forces. Its territory, ports, airfields, surveillance, and access shape what both countries can do in a crisis. Japan’s own defense investments matter to alliance readiness, too. The 2026 defense budget documentation names stand-off missiles, integrated air and missile defense, cross-domain operations, unmanned systems, munitions, and more resilient facilities among its priorities. The ministry also notes the challenge of recruiting and retaining personnel. [3]"},{"type":"heading","text":"The alliance is an operating system, not a slogan","level":2},{"type":"paragraph","text":"The U.S.-Japan alliance is often described as the “cornerstone” of regional stability. That phrase appears in both governments’ formal statements, but its significance is material: it binds U.S. commitments to Japan’s territory and capabilities, while giving Washington an enduring position in the western Pacific. Japan’s security decisions can thus affect the credibility and reach of the wider U.S. alliance network."},{"type":"paragraph","text":"The relationship is also changing. The 2025 leaders’ statement sets out intended cooperation on command structures, extended deterrence, defense equipment co-production, cyber capabilities, and industrial capacity. It also links security to investment, critical technologies, supply-chain resilience, and economic coercion. These are stated intentions and policy directions; a joint statement is not evidence that every proposed measure has already been implemented. [2]"},{"type":"paragraph","text":"Japan’s official defense plan illustrates the operational turn. Its 2026 budget materials say that the Joint Operations Command was established in March 2025 and list investments that span space, cyber, maritime, air, and land capabilities. The same documents say Japan brought forward its target for defense spending equivalent to 2 percent of GDP to FY2025, using a combination of initial and supplementary budgets. That is the government’s accounting description of a spending target, not a guarantee of lasting military superiority. [3]"},{"type":"paragraph","text":"This is a consequential adjustment for a country whose postwar identity has emphasized restraint and whose security policy remains bound by domestic law, public debate, and a deep dependence on the U.S. alliance. Japan’s increased capacity may strengthen deterrence. It can also raise questions at home about cost, local burdens, and how far the country should go in a crisis. The alliance’s future depends not only on hardware but also on whether both societies sustain the political will behind it."},{"type":"heading","text":"Japan’s quiet leverage is industrial","level":2},{"type":"paragraph","text":"Japan is less visible than Taiwan in the global chip story because it is not the main producer of the most advanced logic chips. But that framing misses a central part of the supply chain: chips require specialized materials, components, and manufacturing equipment long before they leave a fabrication plant."},{"type":"paragraph","text":"The OECD’s 2025 study places semiconductors upstream in global production networks and finds that the industry’s value added is highly concentrated, with roughly three-quarters generated by five economies, four of them in Asia. Because chips feed into electronics, vehicles, machinery, and many other products, a disruption can propagate beyond the semiconductor sector. The OECD cautions, in effect, against treating chip supply as an isolated technology issue: its network position makes continuity a broader economic concern. [4]"},{"type":"paragraph","text":"Japan is important in that network as a supplier of critical inputs and specialist tools. Japan’s trade-promotion agency JETRO identifies Japanese firms involved in silicon wafers, photoresist materials, testing, and chip-manufacturing equipment, including Shin-Etsu Chemical, JSR, Advantest, and Tokyo Electron. JETRO also reports a 90 percent global share for Tokyo Electron in photoresist-coating tools, attributing the claim to an industry analyst; that is a company-specific estimate, not an official market census. The broader point is more robust than any single market-share figure: Japan’s industrial role extends well beyond assembling finished electronics. [5]"},{"type":"paragraph","text":"That ecosystem matters to new fabrication plants as well as established suppliers. JETRO describes TSMC’s Kumamoto fab as having been delivered early, and notes the attraction of nearby specialist suppliers, universities, and research capacity. This is one reason Japan’s chip significance cannot be measured only by where the most advanced chips are designed or fabricated: location and supplier networks can determine how quickly capacity is built and maintained. [5]"},{"type":"paragraph","text":"This supplier position gives Japan leverage, but it also creates exposure. Specialized products can be difficult to replace quickly, and the facilities that make them rely on skilled workers, energy, water, and stable logistics. Japan’s own National Security Strategy treats secure supplies of semiconductors and rare earths as part of economic security. [1] The U.S.-Japan critical-minerals framework announced in October 2025 adds plans for joint project selection, public and private financing, stockpiling discussions, and a rapid-response group. It explicitly describes itself as a policy action plan, not a legally binding agreement. [6]"},{"type":"heading","text":"A major power with a shrinking population","level":2},{"type":"paragraph","text":"Japan’s global weight is not captured by nostalgia for its economic heyday—or by the claim that it has become irrelevant. It remains a major industrial and technological economy, but it faces serious constraints on labor, public spending, and long-term growth. The International Monetary Fund’s current country page projects real GDP growth of 0.7 percent in 2026. A forecast is not a verdict; it signals a mature economy expected to grow modestly, not a state in freefall. [7]"},{"type":"paragraph","text":"The demographic constraint is unusually clear. Japan’s Statistics Bureau counted 123.8 million residents in 2024, down by 550,000 from the prior year and the fourteenth consecutive annual decline. People aged 65 or older made up 29.3 percent of the population, a record high in the bureau’s handbook. [8] This puts pressure on the workforce and public finances, even as demand grows for health and care services. The national security strategy itself acknowledges that population decline, low fertility, and fiscal strain are domestic challenges. [1]"},{"type":"paragraph","text":"Those facts complicate the case for Japan as a rising military power. Budgets can buy equipment; they cannot instantly supply trained personnel, reverse aging, or eliminate choices among defense, welfare, and investment. Japan’s 2026 defense plan expressly acknowledges a difficult recruitment environment. [3] Its influence may increasingly depend on using its strengths selectively: alliance coordination, technology, maritime awareness, finance, and partnerships rather than trying to match every rival platform for platform."}]'::jsonb, 'POWER', 8, 'published', 'Why Japan Matters More Than Most People Realize | Omniv', 'When people talk about a crisis around Taiwan, the focus tends to land on Taiwan itself, China, and Washington. But the map tells a wider story. Japan’s southwestern islands sit near Taiwan and the East China Sea; U.S. forces operate from b…', 'https://omniv.media/p/02-japan', '[{"name":"cas.go.jp","title":"National Security Strategy of Japan (December 2022)","url":"https://www.cas.go.jp/jp/siryou/221216anzenhoshou/nss-e.pdf"},{"name":"china.usembassy-china.org.cn","title":"United States-Japan Joint Leaders’ Statement (February 2025)","url":"https://china.usembassy-china.org.cn/united-states-japan-joint-leaders-statement-2/"},{"name":"mod.go.jp","title":"Progress and Budget in Fundamental Reinforcement of Defense Capabilities: Overview of FY2026 Budget","url":"https://www.mod.go.jp/en/d_act/d_budget/pdf/fy2026_20260302a.pdf"},{"name":"oecd.org","title":"Economic Security in a Changing World: Special Focus on Semiconductor Value Chains","url":"https://www.oecd.org/en/publications/2025/09/economic-security-in-a-changing-world_78f3b129/full-report/special-focus-semiconductor-value-chains_dc772986.html"},{"name":"jetro.go.jp","title":"Japan’s Sublime Semiconductor Supply Chain","url":"https://www.jetro.go.jp/en/invest/insights/japan-insight/japan-sublime-semiconductor.html"},{"name":"whitehouse.gov","title":"United States-Japan Framework for Securing the Supply of Critical Minerals and Rare Earths through Mining and Processing","url":"https://www.whitehouse.gov/briefings-statements/2025/10/united-states-japan-framework-for-securing-the-supply-of-critical-minerals-and-rare-earths-through-mining-and-processing/"},{"name":"imf.org","title":"Japan: IMF Country Information and Projections","url":"https://www.imf.org/en/countries/jpn"},{"name":"stat.go.jp","title":"Statistical Handbook of Japan 2025","url":"https://www.stat.go.jp/english/data/handbook/pdf/2025all.pdf"}]'::jsonb, 'Japan’s significance is best understood as a multiplier. Its location magnifies the practical value of the U.S. alliance. Its defense choices help determine whether that alliance can respond credibly in a regional emergency. Its companies sit in specialized segments of the chip and materials economy where a missing input can bottleneck production far beyond Japan’s borders. For China, Japan is an influential neighbor with a U.S. treaty ally role and industrial links that shape the technology environment. For Taiwan, Japan is a nearby country whose bases, policy, and supply-chain position could matter profoundly in a crisis—though what Tokyo would do in any particular contingency cannot be inferred from geography alone. For Washington, Japan is not merely a platform for American power: it is a partner with interests, constraints, and choices of its own. The distinction matters. Treating Japan as a passive extension of the United States understates its agency. Treating it as a self-sufficient counterweight to China overstates its ability to act alone. The strategic reality sits between those two simplifications.', 'The usual question is whether Japan is “rearming.” A better one is: **what kind of regional order can Japan help sustain with the people, resources, and public consent it will actually have?** Tokyo is building more military capacity and deeper security partnerships, while seeking to diversify industrial dependencies and secure critical inputs. But resilience is not the same as self-sufficiency, and military spending is not the same as usable capability. The hard test will be whether Japan can keep its alliances politically durable, its industrial base productive, and its society willing to carry the costs—without mistaking every economic tie for a security vulnerability or every defense investment for a guarantee. That answer will shape far more than Japan’s future. It will help determine whether the Indo-Pacific remains a region where trade and deterrence coexist, or one where the supply chains linking its economies become another arena of coercion.', '[{"type":"project","slug":"japan","label":"Japan"},{"type":"project","slug":"united-states","label":"United States"},{"type":"project","slug":"china","label":"China"},{"type":"project","slug":"taiwan","label":"Taiwan"},{"type":"project","slug":"russia","label":"Russia"},{"type":"company","slug":"tsmc","label":"TSMC"},{"type":"project","slug":"semiconductors","label":"Semiconductors"},{"type":"project","slug":"rare-earths","label":"Rare Earths"},{"type":"project","slug":"global-supply-chains","label":"Global Supply Chains"}]'::jsonb, '{}'::text[], ARRAY['power', 'japan', 'united states', 'china', 'taiwan', 'russia'], '8 min read', 90, '2026-09-26T08:00:00Z') on conflict (slug) do update set publisher_id=excluded.publisher_id, publisher_name=excluded.publisher_name, title=excluded.title, summary=excluded.summary, subtitle=excluded.subtitle, excerpt=excluded.excerpt, content=excluded.content, category_id=excluded.category_id, reading_time=excluded.reading_time, status='published', seo_title=excluded.seo_title, seo_description=excluded.seo_description, canonical_url=excluded.canonical_url, sources=excluded.sources, what_this_means=excluded.what_this_means, question_nobody_asks=excluded.question_nobody_asks, entity_refs=excluded.entity_refs, related_publication_ids=excluded.related_publication_ids, tags=excluded.tags, meta=excluded.meta, heat=excluded.heat, published_at=excluded.published_at, updated_at=now();
insert into public.discovery_publications (publisher_id, publisher_name, type, slug, title, summary, body, subtitle, excerpt, content, category_id, reading_time, status, seo_title, seo_description, canonical_url, sources, what_this_means, question_nobody_asks, entity_refs, related_publication_ids, tags, meta, heat, published_at) values ((select id from public.discovery_entities where type='company' and slug='omniv'), 'Omniv', 'article', '03-russia-north-korea', 'Why Russia and North Korea Are Getting Closer', 'When Vladimir Putin arrived in Pyongyang in June 2024, he and Kim Jong Un signed a treaty that promised more than friendly declarations. It bound their governments to military and other assistance if either were subjected to armed invasion,…', '', 'The Ukraine war turned a once-uneasy relationship into a strategic exchange: Moscow needs ammunition and manpower; Pyongyang wants resources, military know-how and diplomatic cover.', 'When Vladimir Putin arrived in Pyongyang in June 2024, he and Kim Jong Un signed a treaty that promised more than friendly declarations. It bound their governments to military and other assistance if either were subjected to armed invasion,…', '[{"type":"paragraph","text":"When Vladimir Putin arrived in Pyongyang in June 2024, he and Kim Jong Un signed a treaty that promised more than friendly declarations. It bound their governments to military and other assistance if either were subjected to armed invasion, and it set out cooperation across trade, technology, energy, science and security. The treaty entered into force that December. [1] [2]"},{"type":"paragraph","text":"The pact did not create the rapprochement. It gave legal and political form to one already taking shape around Russia’s war against Ukraine. North Korea could offer what Moscow urgently needed: artillery ammunition, missiles and, later, troops. Russia could offer a sanctioned state something it struggles to obtain elsewhere: money and material, military experience, a powerful diplomatic partner, and perhaps access to technologies with military applications. The precise terms of the exchange remain opaque. [3] [4]"},{"type":"heading","text":"War made the relationship useful","level":2},{"type":"paragraph","text":"The timing matters. Moscow and Pyongyang had a long history, but their relationship had cooled after the Soviet Union collapsed. Russia had joined China in supporting United Nations sanctions on North Korea’s nuclear and missile programs. The break with that approach came gradually, as Russia’s invasion of Ukraine isolated it from Western markets and technology and created a sustained demand for weapons. [5]"},{"type":"paragraph","text":"U.S. intelligence assessed in 2024 that North Korea had probably begun shipping munitions to Russia in exchange for diplomatic, economic and military concessions. Subsequent monitoring has documented the scale of the military link. The Multilateral Sanctions Monitoring Team, or MSMT, reported that a participating state assessed that North Korea sent more than 20,000 containers of munitions and related materiel to Russia from September 2023. The report cites a separate open-source estimate of 4.2 million to 5.8 million artillery shells and rockets shipped by sea between August 2023 and March 2025. These are estimates built from different evidence and methods, not a publicly audited tally. [3] [5]"},{"type":"paragraph","text":"North Korea’s contribution grew beyond cargo. In April 2025, Pyongyang publicly acknowledged for the first time that it had sent troops to fight alongside Russian forces in the Kursk region. The MSMT report, drawing on a participating state’s information, says more than 11,000 North Korean troops were deployed in late 2024; Reuters reported that North Korea and Russia had both confirmed the deployment by April 2025. [3] [4]"},{"type":"paragraph","text":"Later totals are less certain. Chatham House reported in September 2026 that South Korea’s Defence Intelligence Agency estimated more than 16,000 North Korean personnel had been sent to Russia since October 2024, and that the North had supplied more than 15 million artillery rounds. Those figures reflect an attributed intelligence estimate; troop rotations, changing definitions and limits on independent access make a single definitive count difficult. [9]"},{"type":"heading","text":"What Pyongyang may be buying","level":2},{"type":"paragraph","text":"For Kim, the exchange offers immediate material value. The MSMT report says Russia supplied refined petroleum above the UN-mandated cap and maintained correspondent banking relations with North Korea. It also reports Russian transfers of air-defence equipment and anti-aircraft missiles, and says Russia trained North Korean troops. The team identifies these as prohibited activities under Security Council resolutions. Its report is based primarily on information supplied by participating governments, international organizations and civil society, and covers January 2024 through April 2025. [3]"},{"type":"paragraph","text":"The battlefield itself may be a form of military education. North Korean soldiers have encountered drone warfare, electronic warfare, artillery coordination and modern logistics in a live conflict. Chatham House argues that this experience could improve North Korea’s capacity to fight in the future. But the degree of learning, and whether Russia has transferred sensitive systems or components beyond what has been publicly documented, remains difficult to establish. [9]"},{"type":"paragraph","text":"There is also a diplomatic return. A permanent Security Council member willing to cooperate with Pyongyang—and to contest sanctions enforcement—reduces North Korea’s isolation. The treaty frames the partnership as opposition to what both governments describe as Western “hegemony.” That is their political language, not a neutral account of the treaty’s effect. The United States’ 2024 intelligence assessment judged that Kim hopes closer Russian ties will bring financial gains, diplomatic support and defense cooperation, and could help his goal of wider acceptance as a nuclear power. [2] [5]"},{"type":"heading","text":"What Moscow gets in return","level":2},{"type":"paragraph","text":"Russia gets supplies that can help sustain a war of attrition. The MSMT says North Korea transferred ballistic missiles and ammunition and sent troops to support Russia’s war effort. North Korea itself publicly cast its deployment as a decision made under the partnership treaty; Putin publicly thanked Kim after the deployment was acknowledged. [3] [4]"},{"type":"paragraph","text":"That support comes with strategic value beyond the front. It signals that Moscow can find partners willing to defy the sanctions regime and allows Russia to present itself as an actor with ties in Northeast Asia. There may also be a labor dimension: the Congressional Research Service notes reports of North Korean workers in Russia, with some possibly employed in violation of UN sanctions. Claims about the amount of compensation and the balance between cash, fuel, food or other goods remain difficult to verify. [1]"},{"type":"paragraph","text":"The relationship also helps Moscow answer its own isolation. The U.S. intelligence community described Russia’s growing ties with North Korea, China and Iran as part of its effort to strengthen defense production and its economy, and to mitigate the costs of sanctions. That is an assessment of Russia’s broader strategy; it does not prove that each deal with Pyongyang was arranged for one single purpose. [5]"},{"type":"heading","text":"A treaty, and a weakening sanctions system","level":2},{"type":"paragraph","text":"The 2024 treaty matters because it raises the political stakes of future cooperation. Its mutual-assistance clause applies if one party is put in a state of war by armed invasion; it is not a blank cheque for every military action. The agreement also provides for broader defense coordination, economic exchanges, cooperation in science and technology, and opposition to unilateral sanctions. [2]"},{"type":"paragraph","text":"Meanwhile, enforcement has become more contested. In March 2024, Russia vetoed renewal of the UN Panel of Experts that monitored sanctions on North Korea. The UN reported that the vote was 13 in favour, Russia against and China abstaining. The veto ended the panel’s mandate, but it did **not** repeal the sanctions themselves. [6]"},{"type":"paragraph","text":"Eleven governments later established the MSMT to investigate and publish information about violations and evasion. That matters, but it is not the same as a UN-appointed monitoring panel: its reports are produced by participating states and do not carry the Security Council’s authority. The MSMT’s inaugural report documents allegations and evidence of prohibited transfers, fuel supplies and training; readers should distinguish its attribution to participating states from an independently adjudicated finding. [3] [7]"}]'::jsonb, 'POWER', 8, 'published', 'Why Russia and North Korea Are Getting Closer | Omniv', 'When Vladimir Putin arrived in Pyongyang in June 2024, he and Kim Jong Un signed a treaty that promised more than friendly declarations. It bound their governments to military and other assistance if either were subjected to armed invasion,…', 'https://omniv.media/p/03-russia-north-korea', '[{"name":"congress.gov","title":"Russia-North Korea Relations, Congressional Research Service, September 18, 2026","url":"https://www.congress.gov/crs-product/IF12760"},{"name":"reuters.com","title":"Key points of North Korea, Russia landmark strategic partnership treaty, Reuters","url":"https://www.reuters.com/world/asia-pacific/key-points-north-korea-russia-landmark-strategic-partnership-treaty-2024-06-20/"},{"name":"msmt.info","title":"Unlawful Military Cooperation including Arms Transfers between North Korea and Russia, MSMT/2025/1","url":"https://msmt.info/view/save/2025/05/29/1085cade-a4b1-4405-94c0-7c980c24fd21-Unlawful_Military_Cooperation_including_Arms_Transfers_between_North_Korea_and_Russia_(MSMT_2025_1).pdf"},{"name":"reuters.com","title":"North Korea confirms troop deployment to Russia as Putin hails ''heroes'', Reuters","url":"https://www.reuters.com/world/north-korea-confirms-troop-deployment-russia-first-time-kcna-report-2025-04-27/"},{"name":"dni.gov","title":"Annual Threat Assessment of the U.S. Intelligence Community, 2024","url":"https://www.dni.gov/files/ODNI/documents/assessments/ATA-2024-Unclassified-Report.pdf"},{"name":"news.un.org","title":"Russia vetoes DPR Korea sanctions resolution, United Nations News","url":"https://news.un.org/en/story/2024/03/1148121"},{"name":"2021-2025.state.gov","title":"Joint Statement on Establishing Multilateral Sanctions Monitoring Team, U.S. Department of State","url":"https://2021-2025.state.gov/joint-statement-on-establishing-multilateral-sanctions-monitoring-team-for-implementation-of-un-security-council-resolutions-regarding-the-dprk/"},{"name":"beyondparallel.csis.org","title":"North Korea and Russia Cooperation, CSIS Beyond Parallel","url":"https://beyondparallel.csis.org/north-korea-russia-cooperation/"},{"name":"chathamhouse.org","title":"North Korea’s military partnership with Russia has consequences far beyond Ukraine, Chatham House, September 9, 2026","url":"https://www.chathamhouse.org/2026/09/north-koreas-military-partnership-russia-has-consequences-far-beyond-ukraine"}]'::jsonb, 'This partnership connects the European war to security calculations in East Asia. North Korean weapons and personnel help Russia’s campaign; in return, access to Russian equipment, expertise or operational feedback could strengthen North Korea’s forces. U.S. government and research assessments warn that improvements in Pyongyang’s missile, space or other military capabilities could matter to South Korea, Japan and the United States. The risk is real, but the public record does not show that Russia has handed North Korea every advanced capability analysts worry about. [1] [5] [8] It also complicates the regional balance without making North Korea a Russian proxy. Pyongyang has its own priorities, and the treaty’s language gives Kim a way to pursue them while presenting the relationship as one between equals. China remains North Korea’s principal economic partner, according to the Congressional Research Service, and the new ties with Russia do not erase that dependence. They may, however, give Pyongyang another source of leverage and give Moscow a larger role in a region where it wants influence. [1] [9] For governments trying to deter North Korea, the challenge is no longer only how to constrain Pyongyang’s access to money and materials. It is how to discourage a feedback loop in which military support for Russia helps North Korea acquire resources and experience, while the erosion of international monitoring makes the exchange harder to track. That problem persists even if the two leaders’ interests eventually diverge. [3] [7]', 'How much of this partnership can each side afford to sustain? The spotlight usually falls on the weapons moving from North Korea to Russia and the Russian technology that may move back. Less visible are the costs: depleted stocks, casualties, sanctions exposure and the resources needed to maintain the relationship. Chatham House notes that North Korea cannot draw down ammunition and manpower indefinitely without affecting its own readiness. Russia, meanwhile, must decide what it is willing to give a partner whose capabilities could alter security on its far eastern flank. [9] The answer will not be found in treaty language alone. Governments disclose only fragments of the exchange, and estimates of shipments, troop totals and compensation vary. What can be said with confidence is narrower but consequential: military cooperation has become public and institutionalized; both governments have acknowledged the troop deployment; and monitors have documented extensive arms transfers and other sanctions violations. The ultimate scale of Russian assistance—and how much Pyongyang has gained from combat experience—remains uncertain. [3] [4]', '[{"type":"project","slug":"russia","label":"Russia"},{"type":"project","slug":"north-korea","label":"North Korea"},{"type":"project","slug":"united-states","label":"United States"},{"type":"project","slug":"china","label":"China"},{"type":"project","slug":"japan","label":"Japan"}]'::jsonb, '{}'::text[], ARRAY['power', 'russia', 'north korea', 'united states', 'china', 'japan'], '8 min read', 90, '2026-09-25T09:00:00Z') on conflict (slug) do update set publisher_id=excluded.publisher_id, publisher_name=excluded.publisher_name, title=excluded.title, summary=excluded.summary, subtitle=excluded.subtitle, excerpt=excluded.excerpt, content=excluded.content, category_id=excluded.category_id, reading_time=excluded.reading_time, status='published', seo_title=excluded.seo_title, seo_description=excluded.seo_description, canonical_url=excluded.canonical_url, sources=excluded.sources, what_this_means=excluded.what_this_means, question_nobody_asks=excluded.question_nobody_asks, entity_refs=excluded.entity_refs, related_publication_ids=excluded.related_publication_ids, tags=excluded.tags, meta=excluded.meta, heat=excluded.heat, published_at=excluded.published_at, updated_at=now();
insert into public.discovery_publications (publisher_id, publisher_name, type, slug, title, summary, body, subtitle, excerpt, content, category_id, reading_time, status, seo_title, seo_description, canonical_url, sources, what_this_means, question_nobody_asks, entity_refs, related_publication_ids, tags, meta, heat, published_at) values ((select id from public.discovery_entities where type='company' and slug='omniv'), 'Omniv', 'article', '04-epstein-files', 'The Epstein Files: What Do the Documents Actually Tell Us?', 'The first thing to know about the Epstein files is that they are not one file, and they are not a verified list of perpetrators. They are a sprawling collection of records from criminal investigations, court proceedings, custody reviews, an…', '', 'An archive can expose how institutions worked—and failed. It is not, by itself, a verdict on everyone whose name appears inside it.', 'The first thing to know about the Epstein files is that they are not one file, and they are not a verified list of perpetrators. They are a sprawling collection of records from criminal investigations, court proceedings, custody reviews, an…', '[{"type":"paragraph","text":"The first thing to know about the Epstein files is that they are not one file, and they are not a verified list of perpetrators. They are a sprawling collection of records from criminal investigations, court proceedings, custody reviews, and other sources. Some are official records. Some record what a witness said. Some are raw tips sent to investigators. A name can appear for many reasons, and the documents do not carry the same evidentiary weight."},{"type":"paragraph","text":"That distinction matters more than the page count. As of January 30, 2026, the Justice Department said it had published nearly 3.5 million pages, along with more than 2,000 videos and 180,000 images, under the Epstein Files Transparency Act. The department also warned that its production included material submitted by members of the public that could be fake or false. The online library says search results may be unreliable for some handwritten or otherwise technically difficult material, and that additional documents may still be identified for release. [2] [7]"},{"type":"paragraph","text":"So what can readers responsibly take from this archive? The answer starts by separating the proven record from accusations, administrative decisions, and unanswered questions."},{"type":"heading","text":"A collection, not a “client list”","level":2},{"type":"paragraph","text":"The phrase “Epstein files” covers different kinds of evidence and paperwork. The 2025 Transparency Act directed the Justice Department to publish unclassified records in its possession related to Epstein, Ghislaine Maxwell, investigations, travel records, people referenced in connection with investigations, government decisions, and Epstein’s detention and death. The law permits limited redactions, including to protect victims’ identifying information and medical privacy, child sexual abuse material, certain active investigations, images of death or injury, and properly classified information. It says records may not be withheld merely to avoid embarrassment, reputational harm, or political sensitivity. [1]"},{"type":"paragraph","text":"The DOJ says its large release was assembled from several sources, including federal cases in Florida and New York, the prosecution of Maxwell, investigations into Epstein’s death, FBI investigations, and an inspector general inquiry. It says the material not produced fell into categories such as duplicates, privileged communications, material covered by statutory exceptions, or items unrelated to the Epstein and Maxwell case files. Those are the department’s descriptions of its collection and review, not a reader’s independent audit of every page. [7]"},{"type":"paragraph","text":"Earlier document releases also came from different processes. For example, the records unsealed in 2024 were from Virginia Giuffre’s civil defamation lawsuit against Maxwell, not a court-certified roster of criminal “clients.” The papers included depositions and other discovery. People named in them ranged from accusers, employees and witnesses to investigators and people mentioned in passing; the great majority were not accused of wrongdoing in those records. [6]"},{"type":"paragraph","text":"That is why context must travel with a name. A contact entry can show that someone’s details were recorded. A flight log can support that a trip was listed. Neither, without further evidence, establishes why someone traveled, what they knew, or whether they committed a crime. A tip in an FBI file is evidence that a tip was made—not proof that it was true. A prosecutor’s charging document is a formal accusation, not a verdict."},{"type":"heading","text":"What the established record says","level":2},{"type":"paragraph","text":"There is a substantial, documented criminal record at the center of the archive. In 2008, Epstein pleaded guilty in Florida state court to felony solicitation of prostitution and procurement of minors to engage in prostitution, according to the Justice Department’s Office of Professional Responsibility (OPR). He served a sentence imposed under the state resolution. [4] [5]"},{"type":"paragraph","text":"In July 2019, federal prosecutors in New York charged Epstein with sex trafficking of minors and conspiracy. Their indictment alleged that he abused dozens of girls, some as young as 14, in New York and Florida between 2002 and 2005, and that employees or associates helped arrange encounters. Those are the allegations in the indictment. Epstein died in federal custody before the case went to trial, so the 2019 charges were never resolved by a jury verdict. [3] [6]"},{"type":"paragraph","text":"Maxwell’s case had a different outcome. A federal jury convicted her in 2021 of sex trafficking and related crimes for helping recruit and groom underage girls for Epstein. That conviction is a judicial finding about Maxwell’s criminal conduct; it does not turn every person mentioned in her records into a participant. [6]"},{"type":"paragraph","text":"The files also illuminate how authorities handled the earlier federal investigation. OPR’s 2020 review says prosecutors prepared a draft 60-count indictment in 2007, then negotiated a non-prosecution agreement that ended the federal investigation in Florida in exchange for a state resolution. Victims were not told about or consulted on the agreement before it was signed. OPR did not find professional misconduct by the attorneys it reviewed, but concluded that then-U.S. Attorney Alexander Acosta exercised poor judgment and that the agreement was a flawed way to address the federal interest. The department separately acknowledged that victims were not treated with the forthrightness and sensitivity it expected. [4] [5]"},{"type":"paragraph","text":"That is a consequential institutional finding. It is also a carefully bounded one: OPR did not find evidence that the decision was driven by Epstein’s wealth, status, or associations, and it did not conclude that prosecutors committed professional misconduct. Readers should not flatten that mixed conclusion into either “nothing went wrong” or “the review proved a corrupt bargain.” [4]"},{"type":"heading","text":"What a mention can—and cannot—prove","level":2},{"type":"paragraph","text":"The most common error in reading these records is to treat proximity as culpability. A person may appear because they were in a phone book, traveled on an aircraft, attended a social event, were asked about in a deposition, worked for Epstein, investigated him, or were accused by someone. These are materially different circumstances. None should be collapsed into a single implication."},{"type":"paragraph","text":"The 2024 civil documents are a clear example. They emerged from a settled defamation case in which Giuffre accused Maxwell of calling her allegations lies. The court’s unsealing process concerned public access to judicial records and privacy—not a criminal trial of every person identified in discovery. The AP’s review of those files described named people as including accusers, witnesses, staff, investigators, public figures and people mentioned without being accused of anything salacious. [6]"},{"type":"paragraph","text":"Even an allegation deserves precise attribution. A statement in a deposition is a witness’s account under questioning. It may be contested, corroborated, withdrawn, or never tested in a criminal trial. The reporting context matters too: AP notes that Giuffre later withdrew an accusation against Alan Dershowitz, saying she may have made a mistake in identifying him; Dershowitz had denied it. That is not a detail to erase when repeating an old claim. [6]"},{"type":"paragraph","text":"The archive’s scale can create a false sense of completeness. Millions of pages sound exhaustive, but the government itself notes that redactions protect victims and that search tools miss or misread some material. The DOJ also says some media submitted by the public could be fabricated. A document’s presence in an official repository establishes that it was collected or released—not necessarily that every statement in it is accurate or that the public has the whole investigative record. [2]"}]'::jsonb, 'PEOPLE', 8, 'published', 'The Epstein Files: What Do the Documents Actually Tell Us? | Omniv', 'The first thing to know about the Epstein files is that they are not one file, and they are not a verified list of perpetrators. They are a sprawling collection of records from criminal investigations, court proceedings, custody reviews, an…', 'https://omniv.media/p/04-epstein-files', '[{"name":"congress.gov","title":"Epstein Files Transparency Act, Public Law 119–38","url":"https://www.congress.gov/119/plaws/publ38/PLAW-119publ38.pdf"},{"name":"justice.gov","title":"Epstein Library, U.S. Department of Justice","url":"https://www.justice.gov/epstein"},{"name":"justice.gov","title":"Indictment, United States v. Jeffrey Epstein","url":"https://www.justice.gov/usao-sdny/press-release/file/1180481/dl"},{"name":"justice.gov","title":"Executive Summary: Investigation into the U.S. Attorney’s Office for the Southern District of Florida’s Resolution of Its 2006–2008 Federal Criminal Investigation of Jeffrey Epstein","url":"https://www.justice.gov/opr/page/file/1336471/dl"},{"name":"justice.gov","title":"Statement on DOJ Office of Professional Responsibility Report on Jeffrey Epstein 2006–2008 Investigation","url":"https://www.justice.gov/archives/opa/pr/statement-doj-office-professional-responsibility-report-jeffrey-epstein-2006-2008"},{"name":"apnews.com","title":"What to know about the unsealed Jeffrey Epstein documents","url":"https://apnews.com/article/jeffrey-epstein-ghislaine-maxwell-virginia-giuffre-3af500d4788ad45301be426628846d71"},{"name":"justice.gov","title":"Department of Justice Publishes 3.5 Million Responsive Pages in Compliance with the Epstein Files Transparency Act","url":"https://www.justice.gov/opa/pr/department-justice-publishes-35-million-responsive-pages-compliance-epstein-files"}]'::jsonb, 'The files are most useful when read as a map of records, not as a shortcut to a verdict. Start with the document type and its origin. Ask who created it, when, and for what purpose. Distinguish an allegation from a finding; distinguish a logged association from evidence of conduct. Then look for corroboration in independent records or a court’s actual decision. This approach does not minimize abuse or excuse institutional failure. Epstein’s 2008 guilty pleas, the federal case brought in 2019, Maxwell’s conviction, and OPR’s criticism of the earlier agreement are not rumors. They are documented events with distinct legal meanings. Taking them seriously also means not extending those findings beyond the people and conduct they establish. The law sought broad disclosure while preserving specific protections, especially for victims. DOJ’s library warns that personal or sensitive material may nevertheless have been inadvertently posted and asks readers to report it. That warning is a reminder that transparency is not a license to republish victim identities or intimate material. Public curiosity should not reproduce the harm these files are meant to illuminate. [1] [2]', 'Beyond “Who is named?”, ask: **How did institutions respond when they had information—and what would it have taken to act differently?** OPR’s account gives one answer worth staying with. Federal investigators developed a case and prosecutors drafted a sweeping indictment, yet the matter was resolved through an agreement that left federal prosecution behind. The review found poor judgment and a failure to communicate candidly with victims, while stopping short of a professional-misconduct finding. That institutional record can be examined without guessing about hidden motives or treating every acquaintance as a suspect. [4] [5] That question also changes what a meaningful disclosure should look like. Pages alone cannot tell the public which leads were tested, why prosecutorial choices were made, whether redactions were correctly applied, or what victims were told. Those questions require traceable explanations from responsible institutions, checked against the records and the law—not viral name counts.', '[{"type":"project","slug":"united-states","label":"United States"}]'::jsonb, '{}'::text[], ARRAY['people', 'united states'], '8 min read', 90, '2026-09-25T08:00:00Z') on conflict (slug) do update set publisher_id=excluded.publisher_id, publisher_name=excluded.publisher_name, title=excluded.title, summary=excluded.summary, subtitle=excluded.subtitle, excerpt=excluded.excerpt, content=excluded.content, category_id=excluded.category_id, reading_time=excluded.reading_time, status='published', seo_title=excluded.seo_title, seo_description=excluded.seo_description, canonical_url=excluded.canonical_url, sources=excluded.sources, what_this_means=excluded.what_this_means, question_nobody_asks=excluded.question_nobody_asks, entity_refs=excluded.entity_refs, related_publication_ids=excluded.related_publication_ids, tags=excluded.tags, meta=excluded.meta, heat=excluded.heat, published_at=excluded.published_at, updated_at=now();
insert into public.discovery_publications (publisher_id, publisher_name, type, slug, title, summary, body, subtitle, excerpt, content, category_id, reading_time, status, seo_title, seo_description, canonical_url, sources, what_this_means, question_nobody_asks, entity_refs, related_publication_ids, tags, meta, heat, published_at) values ((select id from public.discovery_entities where type='company' and slug='omniv'), 'Omniv', 'article', '05-putin-north-korea', 'Putin, Russia and the New Network Around North Korea', 'The train is the telling detail. North Korean ammunition leaves the port of Rajin, crosses the short border into Russia, then travels by rail toward depots nearer the war in Ukraine. A shipment that begins on one isolated peninsula becomes…', '', 'The Moscow–Pyongyang partnership is more than a treaty or an arms deal. It is a growing system of weapons, soldiers, transport links and political protection—with consequences that run from Ukraine to East Asia, and important parts still hidden from view.', 'The train is the telling detail. North Korean ammunition leaves the port of Rajin, crosses the short border into Russia, then travels by rail toward depots nearer the war in Ukraine. A shipment that begins on one isolated peninsula becomes…', '[{"type":"paragraph","text":"The train is the telling detail. North Korean ammunition leaves the port of Rajin, crosses the short border into Russia, then travels by rail toward depots nearer the war in Ukraine. A shipment that begins on one isolated peninsula becomes fuel for another country’s battlefield. Open-source investigators have traced dozens of voyages and the containers they carried; governments have separately documented a second exchange, in which North Korean troops entered Russia’s war. [4] [5]"},{"type":"paragraph","text":"This is the new network around North Korea: not a secret alliance conjured from a single summit, but an increasingly visible chain linking Pyongyang’s weapons and manpower to Moscow’s urgent wartime needs—and Russian resources and diplomatic cover to the North’s long-standing priorities. The exchange is real. Its full price, especially in military technology, is not yet knowable from public evidence."},{"type":"heading","text":"A wartime bargain becomes a public pact","level":2},{"type":"paragraph","text":"The relationship accelerated after Russia’s 2022 invasion of Ukraine. U.S. officials first publicly accused North Korea of supplying ammunition to Russia that year. In September 2023, Kim Jong Un met Vladimir Putin at Russia’s Vostochny Cosmodrome. The following June, Putin travelled to Pyongyang, where the two leaders signed a Comprehensive Strategic Partnership Treaty. The Kremlin announcement also noted agreements on a road bridge and health cooperation. [1] [2]"},{"type":"paragraph","text":"The treaty provides for military assistance if either country is subjected to an armed invasion that puts it in a state of war. That is a consequential commitment, but not a blank cheque for every conflict: the trigger matters. Russia later cited the pact when it acknowledged that North Korean forces had fought alongside Russian troops in the Kursk region. North Korea confirmed its deployment on April 28, 2025. The Kremlin described the troops as allies and heroes; that language is the Russian government’s account, not an independent assessment of the campaign. [1] [3]"},{"type":"paragraph","text":"The announcement ended months of official silence. Reuters reported that Ukraine had put the deployment at roughly 14,000 troops, including reinforcements, while South Korean and U.S. officials had earlier offered varying estimates. Numbers in wartime are difficult to verify independently. The Multilateral Sanctions Monitoring Team (MSMT), drawing on information supplied by participating governments, said more than 11,000 North Korean troops had been deployed to Russia since October 2024. Those figures refer to different reporting and estimate points, not a single settled count. [3] [4]"},{"type":"heading","text":"A logistics chain with battlefield consequences","level":2},{"type":"paragraph","text":"The weapons flow is supported by evidence beyond statements from either capital. The Open Source Centre, working with Reuters, analyzed hundreds of satellite images, ship movements and container configurations. It identified at least 64 voyages by four Russian-flagged vessels between August 2023 and March 2025, and estimated that more than 15,000 containers likely carried between 4.2 million and 5.8 million munitions. The researchers traced the route from Rajin to Russia’s Far East and then by rail toward ammunition depots. The cargo totals are estimates, not a publicly audited manifest. [5]"},{"type":"paragraph","text":"A separate MSMT report, based on material from participating states and other sources, described transfers by sea, air and rail. It said a participating state assessed that shipments since September 2023 amounted to more than 20,000 containers of munitions and related materiel, and that as many as nine million rounds had moved in 2024 alone. The MSMT and Open Source Centre estimates use different evidence and time windows; they should not be collapsed into one precise count. Both point to sustained, large-scale transfers. [4] [5]"},{"type":"paragraph","text":"The MSMT report also said North Korea supplied ballistic missiles and other weapons, and that Russia trained North Korean troops deployed to support its war. It assessed that the cooperation helped Moscow intensify attacks on Ukraine, including strikes on civilian infrastructure. These are findings and assessments in a multilateral monitoring report, not a court judgment. The reported military assistance in both directions violates UN Security Council restrictions, which prohibit arms transfers involving North Korea and military training or assistance to it. [4] [6]"},{"type":"heading","text":"What each side can gain","level":2},{"type":"paragraph","text":"For Russia, ammunition is the immediate return: an external supply that can help sustain artillery fire while its forces fight in Ukraine. North Korean missiles and deployed troops add further support, even if the scale and operational effect of each are contested or hard to measure. Moscow has also made the partnership visible as a strategic choice, rather than treating it as an awkward transaction. [3] [4] [5]"},{"type":"paragraph","text":"For Pyongyang, the bargain can pay in several currencies. Arms sales generate resources; closer links may improve access to food, fuel and other goods; and troops return with experience of modern combat. The MSMT said Moscow was believed to have supplied North Korea with air-defence equipment, anti-aircraft missiles and advanced electronic-warfare systems. These are reported transfers, not a complete inventory. The U.S. intelligence community has described Russian support as bringing North Korea financial benefit, diplomatic backing and defence cooperation. [4]"},{"type":"paragraph","text":"There is a difference between evidence of military cooperation and proof of a particular technology transfer. The two governments have pledged wider scientific cooperation, including in areas such as nuclear energy and space. Analysts and U.S. officials warn that Russia could help North Korea improve missiles, satellites or other advanced capabilities. But public sources do not establish that Moscow has handed Pyongyang any specific nuclear-warhead design, intercontinental-missile breakthrough or submarine technology. The possibility matters; it should not be reported as a completed transfer. [1] [7]"},{"type":"heading","text":"The network includes a fight over who gets to watch","level":2},{"type":"paragraph","text":"This partnership is not just a flow of cargo. It also concerns the institutions that might expose or deter it. In March 2024, Russia vetoed a Security Council resolution to extend the mandate of the UN Panel of Experts that monitored North Korea sanctions. The sanctions themselves remained in force, but the panel’s reporting mandate ended. The United Nations recorded Russia’s stated objections to the sanctions and the vote; the U.S. mission accused Moscow of seeking to suppress scrutiny of its own conduct. The accusation is attributable to Washington, while the veto and its effect on the panel are documented facts. [6]"},{"type":"paragraph","text":"In October 2024, a group of countries formed the MSMT to continue monitoring and reporting on sanctions violations. Its 2025 report documented the troop and weapons flows, Russian training, oil deliveries and financial links it considered unlawful. The new body helps fill an information gap, but it is not a UN Security Council panel and cannot compel access or impose sanctions. It depends on participating states’ evidence and cooperation. [4]"},{"type":"paragraph","text":"That distinction is central to reading the record. The shipments and deployment are no longer merely allegations: Russia and North Korea acknowledged the troops, and independent analysis supports a sustained munitions pipeline. The exact volume, terms of payment, extent of Russian technical help and durability of the partnership are less transparent. Moscow and Pyongyang have incentives to advertise solidarity and conceal sensitive exchanges. Outside governments have incentives to expose them. Neither incentive substitutes for independently verifiable evidence."}]'::jsonb, 'POWER', 7, 'published', 'Putin, Russia and the New Network Around North Korea | Omniv', 'The train is the telling detail. North Korean ammunition leaves the port of Rajin, crosses the short border into Russia, then travels by rail toward depots nearer the war in Ukraine. A shipment that begins on one isolated peninsula becomes…', 'https://omniv.media/p/05-putin-north-korea', '[{"name":"congress.gov","title":"Congressional Research Service, Russia-North Korea Relations","url":"https://www.congress.gov/crs-product/IF12760"},{"name":"en.kremlin.ru","title":"Kremlin, Russia-DPRK talks","url":"https://en.kremlin.ru/events/president/news/74330"},{"name":"reuters.com","title":"Reuters, North Korea confirms troop deployment to Russia as Putin hails ''heroes''","url":"https://www.reuters.com/world/north-korea-confirms-troop-deployment-russia-first-time-kcna-report-2025-04-27/"},{"name":"msmt.info","title":"Multilateral Sanctions Monitoring Team, Unlawful Military Cooperation including Arms Transfers between North Korea and Russia","url":"https://msmt.info/view/save/2025/05/29/1085cade-a4b1-4405-94c0-7c980c24fd21-Unlawful_Military_Cooperation_including_Arms_Transfers_between_North_Korea_and_Russia_(MSMT_2025_1).pdf"},{"name":"opensourcecentre.org","title":"Open Source Centre, Brothers in Arms: Estimating North Korean Munitions Deliveries to Russia","url":"https://opensourcecentre.org/research/brothers-in-arms"},{"name":"news.un.org","title":"UN News, Russia vetoes DPR Korea sanctions resolution","url":"https://news.un.org/en/story/2024/03/1148121"},{"name":"csis.org","title":"CSIS, A Threat Like No Other: Russia–North Korea Military Cooperation","url":"https://www.csis.org/analysis/threat-no-other-russia-north-korea-military-cooperation"}]'::jsonb, 'The most consequential shift is that North Korea is no longer only a distant supplier in Russia’s war. Its soldiers have entered combat, its weapons have crossed borders in large volumes, and a treaty gives the partnership a formal security framework. For Ukraine, that means the war’s supply chain reaches East Asia. For Seoul, Tokyo and Washington, it means decisions made in the European theatre may affect the capabilities and confidence of a heavily armed state in their region. [1] [4] [5] But “alliance” should not become shorthand for a unified command or automatic intervention in every crisis. The treaty’s armed-invasion condition is narrower than an unlimited mutual-defence guarantee. The public record confirms cooperation, not an integrated military structure. It also cannot tell us whether the relationship would hold if Russia’s needs changed, or if the political costs for either leader rose. [1] The key risk is cumulative. Money and supplies can strengthen North Korea’s ability to sustain its weapons programs. Combat experience can teach troops and planners. Russian diplomatic protection can weaken pressure on the sanctions system. Even without proof of a dramatic technology transfer, those incremental gains can complicate deterrence across two theatres at once. Analysts’ warnings about future capabilities describe a risk, not a fact already achieved. [4] [6] [7]', 'What does Pyongyang learn that it does not sell? Ammunition can be counted imperfectly and ships can be watched from orbit. The quieter return may be operational: how its units perform under fire, how its equipment behaves against modern defences, which tactics work and where its weaknesses show. The MSMT explicitly identified first-hand modern-war experience as a benefit. What it cannot yet show is how that learning will be translated into North Korean doctrine, weapons design or future operations. [4] That gap makes the exchange more than a transaction. Russia may receive matériel for a war being fought now; North Korea may receive knowledge whose value compounds over time. It is a plausible strategic reading of the documented deployment—not proof that a specific lesson or technology has already changed the balance. The next evidence to watch is not only the next ship, but visible changes in North Korea’s systems, training and doctrine that can be tied to this relationship.', '[{"type":"project","slug":"russia","label":"Russia"},{"type":"project","slug":"north-korea","label":"North Korea"},{"type":"project","slug":"united-states","label":"United States"},{"type":"project","slug":"china","label":"China"},{"type":"project","slug":"japan","label":"Japan"}]'::jsonb, '{}'::text[], ARRAY['power', 'russia', 'north korea', 'united states', 'china', 'japan'], '7 min read', 90, '2026-09-24T09:00:00Z') on conflict (slug) do update set publisher_id=excluded.publisher_id, publisher_name=excluded.publisher_name, title=excluded.title, summary=excluded.summary, subtitle=excluded.subtitle, excerpt=excluded.excerpt, content=excluded.content, category_id=excluded.category_id, reading_time=excluded.reading_time, status='published', seo_title=excluded.seo_title, seo_description=excluded.seo_description, canonical_url=excluded.canonical_url, sources=excluded.sources, what_this_means=excluded.what_this_means, question_nobody_asks=excluded.question_nobody_asks, entity_refs=excluded.entity_refs, related_publication_ids=excluded.related_publication_ids, tags=excluded.tags, meta=excluded.meta, heat=excluded.heat, published_at=excluded.published_at, updated_at=now();
insert into public.discovery_publications (publisher_id, publisher_name, type, slug, title, summary, body, subtitle, excerpt, content, category_id, reading_time, status, seo_title, seo_description, canonical_url, sources, what_this_means, question_nobody_asks, entity_refs, related_publication_ids, tags, meta, heat, published_at) values ((select id from public.discovery_entities where type='company' and slug='omniv'), 'Omniv', 'article', '06-taiwan', 'Why Taiwan Sits at the Center of the U.S.–China Relationship', 'A disruption in the Taiwan Strait would not stay in the Taiwan Strait. It could test the limits of U.S. policy, unsettle American allies, interrupt trade routes, and expose how much of the world’s advanced computing depends on production cl…', '', 'Taiwan’s importance is not just a question of who governs an island. It is where security commitments, advanced computing, and the busiest routes of East Asian trade converge—and where none of those interests comes with a guarantee of peace.', 'A disruption in the Taiwan Strait would not stay in the Taiwan Strait. It could test the limits of U.S. policy, unsettle American allies, interrupt trade routes, and expose how much of the world’s advanced computing depends on production cl…', '[{"type":"paragraph","text":"A disruption in the Taiwan Strait would not stay in the Taiwan Strait. It could test the limits of U.S. policy, unsettle American allies, interrupt trade routes, and expose how much of the world’s advanced computing depends on production clustered on one island."},{"type":"paragraph","text":"That is why Taiwan occupies a place in the U.S.–China relationship out of proportion to its size. The island is a self-governing democracy with a central role in semiconductor manufacturing. Beijing claims Taiwan as part of China and has not renounced the use of force to bring it under its control. Washington recognizes the People’s Republic of China (PRC) as the government of China, but maintains extensive unofficial relations with Taiwan under U.S. law. These are documented positions; what either side would do in a crisis is less certain. [1] [2]"},{"type":"heading","text":"A status that is deliberately unresolved","level":2},{"type":"paragraph","text":"Since 1979, the United States has maintained formal diplomatic relations with Beijing and unofficial relations with Taiwan. U.S. policy is guided by the Taiwan Relations Act, three U.S.–China joint communiqués, and the Six Assurances. That is not the same thing as adopting Beijing’s “one China” principle. The United States acknowledges the Chinese position that there is one China and Taiwan is part of it; it does not itself endorse Beijing’s claim to sovereignty over Taiwan. [1]"},{"type":"paragraph","text":"The Taiwan Relations Act makes peace in the Western Pacific a U.S. political, security, and economic interest. It directs the United States to make defensive arms available to Taiwan and to maintain the capacity to resist force or coercion that would jeopardize the island’s security or social and economic system. The act does not promise that U.S. forces will automatically enter a war. That gap—between preparing to resist coercion and not specifying what Washington would do—is commonly called “strategic ambiguity.” [2] [1]"},{"type":"paragraph","text":"This structure leaves hard questions open by design. It is meant to discourage Beijing from using force, while also discouraging Taipei from assuming that any unilateral change to the status quo would receive automatic U.S. backing. Washington says it opposes unilateral changes and expects cross-strait differences to be resolved peacefully. [1]"},{"type":"paragraph","text":"The ambiguity is a policy choice, not a prediction that a crisis will remain controllable. Chinese military pressure has increased, and Taiwan’s status remains disputed. The U.S. Defense Department’s 2025 report describes Beijing’s military exercises around Taiwan in 2024 as including simulated blockade operations. That is the Pentagon’s assessment of the exercises, not proof that a blockade has been ordered or that conflict is inevitable. [3]"},{"type":"heading","text":"The semiconductor concentration behind the headlines","level":2},{"type":"paragraph","text":"Taiwan’s technology role gives the relationship global economic weight. The Congressional Research Service reported in March 2026 that Taiwan produces about 90 percent of global advanced chips. Those components power high-performance computing, smartphones, data centers, and other products. [6]"},{"type":"paragraph","text":"The manufacturing system is more than one company or one fabrication plant. Taiwan’s foundry model lets specialized chip designers outsource production to contract manufacturers rather than operate their own factories. A 2024 U.S. International Trade Commission briefing estimated that Taiwan captured nearly 70 percent of global foundry revenue in recent years, and that TSMC was the world’s largest foundry. The briefing also noted that Taiwan’s semiconductor industry is deeply connected to exports and the wider economy. Its estimates of capacity largely use 2021 data, so the newer CRS figure is a better snapshot for the advanced-chip share today. [4] [6]"},{"type":"paragraph","text":"TSMC’s 2025 annual report shows both the scale and the geographic imbalance. The company reported manufacturing 12,682 products for 534 customers that year, and said its annual capacity exceeded 17 million 12-inch-equivalent wafers. It manages facilities in Taiwan as well as in Japan, China, the United States, and elsewhere, but its annual report still lists its main production base in Taiwan. Its 3-nanometer technology represented 24 percent of wafer revenue in 2025. [5]"},{"type":"paragraph","text":"Those numbers describe a sophisticated, international network, not an island making every part of every chip. Designers, equipment makers, materials suppliers, packaging firms, customers, and shipping routes are spread across borders. Still, the most advanced manufacturing capacity is unusually concentrated. If production stopped abruptly, other sites could not simply reproduce all of it overnight. The speed and scale of replacement would depend on the technology, available capacity, equipment, skilled labor, and power and water."},{"type":"paragraph","text":"The concentration is also changing, but gradually. TSMC said in March 2025 that it intended to expand its planned U.S. investment to $165 billion, including new fabs, advanced-packaging facilities, and a research center. That was a company announcement of intended investment, not evidence that all those facilities were already built or producing. TSMC’s 2025 annual report lists operations in Arizona and Japan, among other places. [8] [5]"},{"type":"paragraph","text":"Building capacity abroad can add resilience. It does not remove the short-run consequences of a Taiwan disruption, nor does it relocate Taiwan’s existing industrial ecosystem. It also introduces practical tradeoffs: chip factories require substantial capital, specialized workers, reliable infrastructure, and close coordination with suppliers and customers. The USITC briefing identifies energy and water reliability, natural disasters, and geopolitical tension among the industry’s vulnerabilities. [4]"},{"type":"heading","text":"A strategic location and a commercial artery","level":2},{"type":"paragraph","text":"Geography matters independently of chips. Taiwan sits between the East and South China seas, along routes that connect China, Japan, South Korea, Southeast Asia, and the wider Pacific. A military crisis could affect access to the island, but even a coercive measure short of invasion—such as an attempted quarantine or shipping restrictions—could make commercial operators reassess whether vessels should pass nearby. These are plausible risks, not events that have occurred. [3] [7]"},{"type":"paragraph","text":"A 2024 CSIS analysis estimated that 30 percent of Japan’s imports and 25 percent of its exports, together worth nearly $413 billion, passed through the Taiwan Strait in 2024. It estimated that South Korea relied on the strait for 24 percent of imports and 20 percent of exports, worth about $300 billion. These figures are model-based estimates of trade passing through the waterway, not losses forecast for a particular crisis. [7]"},{"type":"paragraph","text":"The distinction matters. A disruption would not necessarily close the strait, and ships could sometimes reroute. But rerouting can mean longer voyages, higher insurance costs, missed port calls, delays, and altered access to fuel and components. The effects would vary by route and type of disruption. Japan and South Korea—both U.S. allies and advanced manufacturing economies—would be exposed alongside China and Taiwan. [7]"},{"type":"paragraph","text":"The United States is connected through trade and technology as well. CRS ranked Taiwan the United States’ fifth-largest merchandise trading partner in 2025, with $256.1 billion in goods trade. The same report noted strong growth in Taiwan’s exports to the U.S., reflecting demand for chips and electronics as well as shifts in production and trade. The economic relationship is substantial, though trade figures alone cannot show the precise cost of a conflict. [6]"},{"type":"heading","text":"Deterrence, alliances, and the limits of a “silicon shield”","level":2},{"type":"paragraph","text":"Taiwan’s semiconductor importance is sometimes presented as a deterrent: because disruption would harm everyone, no one would risk it. The logic is incomplete. Mutual economic exposure can raise the cost of conflict, but it cannot guarantee that political leaders will place those costs above strategic aims. Nor would a crisis need to begin with an invasion. Cyber operations, exercises, economic pressure, or a maritime quarantine could create serious disruption while remaining below the threshold of a declared war. The Defense Department has described military, economic, and information pressure as parts of Beijing’s broader approach toward Taiwan. [3]"},{"type":"paragraph","text":"This is why the Taiwan issue reaches beyond a bilateral dispute. For Washington, it involves the credibility and practical meaning of commitments under U.S. law, and the confidence of regional allies. For Beijing, it is tied to a core sovereignty claim and the PRC’s stated aim of unification. For Taiwan’s people, it concerns the future of the democratic institutions that govern them. Those interests overlap, but they are not identical. [1] [2] [3]"},{"type":"paragraph","text":"The uncertainty is genuine. U.S. law calls for arms and capacity to resist coercion, but it does not specify a guaranteed military response. Analysts can describe scenarios and incentives, but cannot know in advance how decisions would unfold in a particular emergency. Deterrence depends not only on capability, but on perceptions—what each side believes the others will do. [1] [2]"}]'::jsonb, 'TECHNOLOGY', 8, 'published', 'Why Taiwan Sits at the Center of the U.S.–China Relationship | Omniv', 'A disruption in the Taiwan Strait would not stay in the Taiwan Strait. It could test the limits of U.S. policy, unsettle American allies, interrupt trade routes, and expose how much of the world’s advanced computing depends on production cl…', 'https://omniv.media/p/06-taiwan', '[{"name":"congress.gov","title":"Taiwan: Background and U.S. Relations — Congressional Research Service","url":"https://www.congress.gov/crs-product/IF10275"},{"name":"congress.gov","title":"H.R.2479 — Taiwan Relations Act — Congress.gov","url":"https://www.congress.gov/bill/96th-congress/house-bill/2479"},{"name":"media.defense.gov","title":"2025 Annual Report to Congress: Military and Security Developments Involving the People''s Republic of China — U.S. Department of Defense","url":"https://media.defense.gov/2025/Dec/23/2003849070/-1/-1/1/ANNUAL-REPORT-TO-CONGRESS-MILITARY-AND-SECURITY-DEVELOPMENTS-INVOLVING-THE-PEOPLES-REPUBLIC-OF-CHINA-2025.PDF"},{"name":"usitc.gov","title":"Taiwan—The Silicon Island — U.S. International Trade Commission","url":"https://www.usitc.gov/publications/332/executive_briefings/ebot_silicon_island_taiwan_semiconductor.pdf"},{"name":"investor.tsmc.com","title":"TSMC 2025 Annual Report","url":"https://investor.tsmc.com/static/annualReports/2025/english/index.html"},{"name":"congress.gov","title":"U.S.-Taiwan Trade and Economic Relations — Congressional Research Service","url":"https://www.congress.gov/crs-product/IF10256"},{"name":"features.csis.org","title":"How Much Trade Transits the Taiwan Strait? — CSIS","url":"https://features.csis.org/chinapower/china-taiwan-strait-trade/"},{"name":"pr.tsmc.com","title":"TSMC Intends to Expand Its Investment in the United States to US$165 Billion to Power the Future of AI — TSMC","url":"https://pr.tsmc.com/english/news/3210"}]'::jsonb, 'Taiwan is central because several systems meet there: a contested political status, the geography of East Asian security, high-end chip production, and trade routes on which neighboring economies depend. None of these factors alone explains the full strategic risk. Together, they make the consequences of miscalculation unusually wide-ranging. For technology companies and consumers, the practical lesson is not that a chip shortage is certain or that Taiwan’s role will disappear as new factories open elsewhere. It is that diversification takes time, and supply chains remain exposed to disruptions that cannot be solved by adding factory capacity alone. For governments, resilience means preparing for interruptions while keeping communication open and reducing the chance that a coercive move is mistaken for a limited one—or that restraint is mistaken for permission. The most consequential facts are clear: Taiwan is self-governed; Beijing claims it and retains force as an option; U.S. policy supports Taiwan’s self-defense but leaves the military response unspecified; and global advanced-chip production remains concentrated there. The path from those facts to crisis, however, is not predetermined. [1] [2] [3] [6]', 'How much resilience is enough if the thing being protected cannot be moved quickly? It is easy to count announced factories and estimate the value of trade. It is harder to replace an accumulated industrial ecosystem: experienced engineers, reliable utilities, specialist suppliers, production know-how, and the relationships that allow a new process to reach volume. TSMC’s overseas investments matter, but the company’s own disclosures distinguish existing operations from plans still to be built. The question is therefore not whether production can diversify—it already is—but whether diversification can advance faster than strategic risk grows. [5] [8] There is no precise number that answers that. Even a less dramatic shock than war could halt shipments, delay inputs, or undermine confidence. A credible discussion of resilience has to consider those incremental disruptions, as well as the worst case.', '[{"type":"project","slug":"united-states","label":"United States"},{"type":"project","slug":"china","label":"China"},{"type":"project","slug":"taiwan","label":"Taiwan"},{"type":"project","slug":"japan","label":"Japan"},{"type":"company","slug":"tsmc","label":"TSMC"},{"type":"project","slug":"semiconductors","label":"Semiconductors"},{"type":"project","slug":"artificial-intelligence","label":"Artificial Intelligence"},{"type":"project","slug":"global-supply-chains","label":"Global Supply Chains"}]'::jsonb, '{}'::text[], ARRAY['technology', 'united states', 'china', 'taiwan', 'japan', 'tsmc'], '8 min read', 90, '2026-09-24T08:00:00Z') on conflict (slug) do update set publisher_id=excluded.publisher_id, publisher_name=excluded.publisher_name, title=excluded.title, summary=excluded.summary, subtitle=excluded.subtitle, excerpt=excluded.excerpt, content=excluded.content, category_id=excluded.category_id, reading_time=excluded.reading_time, status='published', seo_title=excluded.seo_title, seo_description=excluded.seo_description, canonical_url=excluded.canonical_url, sources=excluded.sources, what_this_means=excluded.what_this_means, question_nobody_asks=excluded.question_nobody_asks, entity_refs=excluded.entity_refs, related_publication_ids=excluded.related_publication_ids, tags=excluded.tags, meta=excluded.meta, heat=excluded.heat, published_at=excluded.published_at, updated_at=now();
insert into public.discovery_publications (publisher_id, publisher_name, type, slug, title, summary, body, subtitle, excerpt, content, category_id, reading_time, status, seo_title, seo_description, canonical_url, sources, what_this_means, question_nobody_asks, entity_refs, related_publication_ids, tags, meta, heat, published_at) values ((select id from public.discovery_entities where type='company' and slug='omniv'), 'Omniv', 'article', '07-chip-war', 'The Chip War Isn''t Really About Chips', 'A chip smaller than a fingernail can hold up a car, a data center, or a weapons system. That sounds like a contradiction: how can something so tiny matter so much? Because the chip is only the visible end of a production system that spans d…', '', 'It is a contest over who can design, make, and restrict the small components on which modern economies—and increasingly military power—depend. Taiwan is the sharpest point of exposure, but the leverage is distributed across a global chain.', 'A chip smaller than a fingernail can hold up a car, a data center, or a weapons system. That sounds like a contradiction: how can something so tiny matter so much? Because the chip is only the visible end of a production system that spans d…', '[{"type":"paragraph","text":"A chip smaller than a fingernail can hold up a car, a data center, or a weapons system. That sounds like a contradiction: how can something so tiny matter so much? Because the chip is only the visible end of a production system that spans design software, specialized equipment, chemicals, fabrication plants, packaging, and skilled labor. A bottleneck at any one stage can matter more than the number of chips on a loading dock."},{"type":"paragraph","text":"That is why the contest over semiconductors is not simply a race to build the fastest processor. It is a struggle over strategic dependence: who can make the most capable chips, who can reach the tools required to make them, and who can withstand a disruption—or impose one. Governments call this national security. Companies call it supply-chain risk. Both are describing the same economic fact from different sides."},{"type":"heading","text":"One product, many chokepoints","level":2},{"type":"paragraph","text":"There is no single “chip supply chain.” A semiconductor may be designed in one country, fabricated in another, and assembled and tested somewhere else. The stages require different expertise, companies, and machinery. Some firms specialize in design and outsource manufacturing; others, including Taiwan Semiconductor Manufacturing Company (TSMC), specialize in manufacturing chips designed by customers."},{"type":"paragraph","text":"The model is efficient precisely because it is specialized. It also means national self-sufficiency is not a realistic near-term description of how the industry works. The OECD’s 2025 mapping describes a complex, globally distributed chain with concentrated critical inputs, specialized economies, and growing trade dependencies. It argues that resilience depends in part on diversification and international cooperation, not just on counting factories inside national borders. [1]"},{"type":"paragraph","text":"In a separate analysis using 2018 data, the OECD found that five economies generated about 75% of semiconductor-industry value added, four of them in Asia. It also noted that concentration differs by chip type: in 2021, the top three exporters of memory chips accounted for more than 80% of exports, while the top three for logic and other chips accounted for more than 55%. Those are measures of economic activity and exports, not a claim that all chips are made in one place. [2]"},{"type":"paragraph","text":"For advanced logic—the chips central to leading-edge computing—the concentration is sharper. The OECD cited 2022 evidence that only TSMC in Taiwan and Samsung in South Korea produced the most advanced logic chips at the time. Its newer capacity study emphasizes why a map of factories is not enough: production plants are not freely interchangeable, and a disruption in one facility cannot necessarily be offset by another making a different chip or using a different process. [2] [3]"},{"type":"paragraph","text":"Taiwan stands out, but it is not the whole story. A U.S. Commerce Department market guide says Taiwan accounts for more than 60% of global foundry revenue and more than 90% of leading-edge chip manufacturing; it put the island’s semiconductor-industry revenue above $165 billion in 2024. Revenue shares and output shares are not identical measures, and the guide does not mean Taiwan makes every kind of semiconductor. The figures do show why a crisis around the island would be an economic shock well beyond the region. [4]"},{"type":"heading","text":"Why geography became security policy","level":2},{"type":"paragraph","text":"A factory’s location has become a geopolitical question because chips are both ordinary commercial inputs and building blocks for advanced computing, artificial intelligence, and military systems. The U.S. government’s stated case for restricting certain exports to China is that advanced chips and the equipment used to make them could support military modernization. That is the government’s rationale, not proof that every chip or every Chinese buyer has a military purpose. [5]"},{"type":"paragraph","text":"China has also made technological independence an explicit policy aim. A Congressional Research Service report describes the State Council’s 2020 framework for supporting the integrated-circuit industry and software, including incentives for capabilities across design, fabrication, equipment, software, packaging, and materials. That documents a state-led industrial strategy; it does not, by itself, establish that every Chinese company or investment acts on government direction. [6]"},{"type":"paragraph","text":"Export controls work through the chain’s dependencies. They can restrict specified chips, manufacturing equipment, design tools, software, or transactions involving listed entities. In December 2024, the U.S. Bureau of Industry and Security announced controls covering 24 types of semiconductor-manufacturing equipment, three types of software tools, high-bandwidth memory, and additions to the Entity List. BIS said the package aimed to impede China’s ability to produce advanced-node chips for military applications. [7]"},{"type":"paragraph","text":"But these rules do not make the chain disappear, nor do they amount to a blanket embargo on every semiconductor. CRS noted in 2025 that some advanced items can still be licensed and that China retains access to portions of the chain, including mature-node technologies, some equipment and tools, research, materials, and third-country computing. It also outlines potential workarounds and enforcement gaps. The practical reach of a control depends on technical thresholds, licensing decisions, allied cooperation, and whether firms can route around it. [5]"},{"type":"paragraph","text":"Policy can change, too. A January 2026 Federal Register rule moved certain exports of advanced-computing chips—including Nvidia’s H200 or equivalents—to China and Macau from a presumption of denial to case-by-case review, if specified conditions are met. Those include certification of adequate U.S. supply, no diversion of foundry capacity from U.S. customers, customer security procedures, and independent testing. Other covered transactions remain subject to a presumption of denial. The change illustrates a live tension: restricting access to capabilities while also weighing commercial supply, U.S. firms’ position, and control over how products are used. [8]"},{"type":"heading","text":"Subsidies are part of the contest","level":2},{"type":"paragraph","text":"The other side of economic security is building capacity at home. In November 2024, the U.S. Commerce Department announced a final award of up to $6.6 billion in direct CHIPS Act funding and up to $5 billion in loans to TSMC Arizona, supporting a planned investment of more than $65 billion in three Phoenix-area fabs. The grant is milestone-based; the investment and job numbers in the announcement are plans and estimates, not all completed outcomes. [9]"},{"type":"paragraph","text":"The public case is to create a more reliable domestic source for strategically important chips and attract a cluster of suppliers and workers. There is evidence of progress: TSMC says its first Arizona fab began high-volume production of N4 chips in the fourth quarter of 2024. But Arizona is not an overnight replacement for Taiwan’s manufacturing ecosystem. The U.S. government’s project page gives later target dates for the second and third fabs, and describes advanced packaging as a future capability. Fabrication capacity is only one link; supply reliability also depends on process maturity, yields, materials, workforce, customer qualification, and packaging. [10] [11]"},{"type":"paragraph","text":"“Reshoring” can therefore be a misleading finish line. Building another fab changes the geography of some production. It does not automatically reproduce the network of suppliers, trained teams, customers, and complementary facilities that took decades to assemble. Nor does it guarantee that a fab can substitute for a different factory’s output during a crisis. The OECD’s latest capacity mapping specifically warns that production capacity is concentrated and that substitutability among plants is limited. [3]"}]'::jsonb, 'TECHNOLOGY', 8, 'published', 'The Chip War Isn''t Really About Chips | Omniv', 'A chip smaller than a fingernail can hold up a car, a data center, or a weapons system. That sounds like a contradiction: how can something so tiny matter so much? Because the chip is only the visible end of a production system that spans d…', 'https://omniv.media/p/07-chip-war', '[{"name":"oecd.org","title":"OECD, Mapping the semiconductor value chain (2025)","url":"https://www.oecd.org/en/publications/mapping-the-semiconductor-value-chain_4154cdbf-en.html"},{"name":"oecd.org","title":"OECD, Economic Security in a Changing World: Semiconductor Value Chains (2025)","url":"https://www.oecd.org/en/publications/2025/09/economic-security-in-a-changing-world_78f3b129/full-report/special-focus-semiconductor-value-chains_dc772986.html"},{"name":"oecd.org","title":"OECD, The chip landscape: Geographical distribution of wafer fabrication capacity (2025)","url":"https://www.oecd.org/en/publications/the-chip-landscape_02dbd028-en.html"},{"name":"trade.gov","title":"U.S. International Trade Administration, Taiwan: Semiconductors including chip design for AI","url":"https://www.trade.gov/country-commercial-guides/taiwan-semiconductors-including-chip-design-ai"},{"name":"congress.gov","title":"Congressional Research Service, U.S. Export Controls and China: Advanced Semiconductors (2025)","url":"https://www.congress.gov/crs-product/R48642"},{"name":"congress.gov","title":"Congressional Research Service, China’s New Semiconductor Policies: Issues for Congress (2021)","url":"https://www.congress.gov/crs-product/R46767"},{"name":"bis.gov","title":"U.S. Bureau of Industry and Security, Commerce Strengthens Export Controls (2024)","url":"https://www.bis.gov/press-release/commerce-strengthens-export-controls-restrict-chinas-capability-produce-advanced-semiconductors-military"},{"name":"federalregister.gov","title":"Federal Register, Revision to License Review Policy for Advanced Computing Commodities (2026)","url":"https://www.federalregister.gov/documents/2026/01/15/2026-00789/revision-to-license-review-policy-for-advanced-computing-commodities"},{"name":"commerce.gov","title":"U.S. Department of Commerce, CHIPS Incentives Award with TSMC Arizona (2024)","url":"https://www.commerce.gov/news/press-releases/2024/11/biden-harris-administration-announces-chips-incentives-award-tsmc"},{"name":"tsmc.com","title":"TSMC Arizona, project milestones and manufacturing status","url":"https://www.tsmc.com/static/abouttsmcaz/index.htm"},{"name":"nist.gov","title":"NIST CHIPS for America, TSMC Arizona project summary","url":"https://www.nist.gov/chips/tsmc-arizona-phoenix"}]'::jsonb, 'The chip war is better understood as competition to shape interdependence than as a race toward total independence. Governments want fewer single points of failure and more control over technologies that could carry military consequences. Companies still depend on cross-border expertise and markets to make production viable. The two aims can coexist, but they also collide: duplicating capacity is costly, while concentrating capacity is risky. For consumers, the conflict may surface as delays or higher costs, but not every geopolitical headline translates into an immediate shortage. The effects depend on what is disrupted, how long it lasts, which chips are affected, inventories, and whether another qualified source exists. A foundry’s capacity figure alone cannot answer those questions. For policymakers, the key distinction is between resilience and autarky. More geographic options can reduce exposure. Yet controls that are too broad may encourage rival systems, invite retaliation, or make coordination with equipment-producing allies harder. These are policy trade-offs, not settled outcomes. The OECD calls for better data and cooperation; the U.S. controls and subsidy programs show Washington’s chosen instruments, but their long-term industrial and security results remain uncertain. [1] [3] [5]', 'If a government says it wants “secure supply,” secure for whom—and secure against what? A factory on national soil may still rely on imported chemicals, equipment, intellectual property, or customers abroad. A local chip supply can be less exposed to one risk and more exposed to another. And a company that can manufacture a chip is not necessarily able to design it, package it, or replace another firm’s output at short notice. The less dramatic but more useful question is not “Where are the chips?” It is “Which specific capability would fail first, who else can provide it, and how long would substitution take?” The available public data do not answer that for every process, firm, or crisis. The OECD’s call for better disaggregated capacity data reflects this limitation. A supply chain cannot be made resilient by rhetoric alone; it requires knowing where its irreplaceable steps are, and accepting that diversification has a cost. [3]', '[{"type":"project","slug":"united-states","label":"United States"},{"type":"project","slug":"china","label":"China"},{"type":"project","slug":"taiwan","label":"Taiwan"},{"type":"project","slug":"japan","label":"Japan"},{"type":"company","slug":"tsmc","label":"TSMC"},{"type":"project","slug":"semiconductors","label":"Semiconductors"},{"type":"project","slug":"artificial-intelligence","label":"Artificial Intelligence"},{"type":"project","slug":"global-supply-chains","label":"Global Supply Chains"}]'::jsonb, '{}'::text[], ARRAY['technology', 'united states', 'china', 'taiwan', 'japan', 'tsmc'], '8 min read', 90, '2026-09-23T09:00:00Z') on conflict (slug) do update set publisher_id=excluded.publisher_id, publisher_name=excluded.publisher_name, title=excluded.title, summary=excluded.summary, subtitle=excluded.subtitle, excerpt=excluded.excerpt, content=excluded.content, category_id=excluded.category_id, reading_time=excluded.reading_time, status='published', seo_title=excluded.seo_title, seo_description=excluded.seo_description, canonical_url=excluded.canonical_url, sources=excluded.sources, what_this_means=excluded.what_this_means, question_nobody_asks=excluded.question_nobody_asks, entity_refs=excluded.entity_refs, related_publication_ids=excluded.related_publication_ids, tags=excluded.tags, meta=excluded.meta, heat=excluded.heat, published_at=excluded.published_at, updated_at=now();
insert into public.discovery_publications (publisher_id, publisher_name, type, slug, title, summary, body, subtitle, excerpt, content, category_id, reading_time, status, seo_title, seo_description, canonical_url, sources, what_this_means, question_nobody_asks, entity_refs, related_publication_ids, tags, meta, heat, published_at) values ((select id from public.discovery_entities where type='company' and slug='omniv'), 'Omniv', 'article', '08-china-supply-chain', 'Why China Wants Control of More of the Technology Supply Chain', 'When China tightened controls on rare earth exports in April 2025, the consequences did not stay inside China. Automakers and other manufacturers abroad scrambled to secure magnets, and some production lines faced shortages. The episode exp…', '', 'Beijing’s drive for technological self-reliance is about more than making chips at home. It is a strategy to reduce vulnerability to foreign pressure—and to preserve leverage in the industries the rest of the world still needs.', 'When China tightened controls on rare earth exports in April 2025, the consequences did not stay inside China. Automakers and other manufacturers abroad scrambled to secure magnets, and some production lines faced shortages. The episode exp…', '[{"type":"paragraph","text":"When China tightened controls on rare earth exports in April 2025, the consequences did not stay inside China. Automakers and other manufacturers abroad scrambled to secure magnets, and some production lines faced shortages. The episode exposed a basic fact of modern industry: a country need not dominate every stage of a technology to exert influence over it. Sometimes control of one difficult-to-replace ingredient is enough. [6] [8]"},{"type":"paragraph","text":"That leverage is one reason China wants greater control over its technology supply chain. Another is vulnerability. Advanced chips, chipmaking equipment and other critical technologies remain tied to foreign suppliers and export rules. Beijing’s response is to build more of the chain at home—from foundational research and components to manufacturing and deployment—while retaining the ability to use its existing industrial strengths abroad."},{"type":"paragraph","text":"The ambition is neither a complete retreat from global trade nor proof that China can already produce every critical technology independently. It is an effort to make dependence less dangerous, and to turn selected points of dependence into bargaining power."},{"type":"heading","text":"Self-reliance is a security policy—and an industrial policy","level":2},{"type":"paragraph","text":"China’s official policy language makes the priority plain. In outlining the 2026–2030 science and technology agenda, the country’s science minister called for “high-level sci-tech self-reliance,” breakthroughs across key technologies and a stronger national system for coordinating innovation. The named priorities include integrated circuits, industrial machinery and high-end instruments. [1]"},{"type":"paragraph","text":"The next five-year blueprint, released in March 2026, places AI adoption, chip breakthroughs and foundational research prominently in the national program. Reuters reported that it calls for AI across the economy, from manufacturing to services, and for progress in fields including quantum technology and robotics. Those aims are official commitments, not evidence that China has already achieved leadership in every one of them. [2]"},{"type":"paragraph","text":"The commercial logic is just as important. Domestic suppliers can serve a huge home market, learn through repeated production, and sell into global markets. China’s earlier “Made in China 2025” initiative set ambitious goals to move up the value chain. A 2025 U.S.-China Economic and Security Review Commission review found that China fell short in some targeted sectors—including integrated circuits—but still expanded capabilities and market share. The report’s broader conclusion was that state support and production scale helped make Chinese manufacturing more competitive. [5]"},{"type":"paragraph","text":"That combination matters. Support for domestic industry may lower dependence on imported technology, but it can also create firms with the scale to compete internationally. Self-reliance and export ambition are not opposites; they can reinforce one another."},{"type":"heading","text":"Chips reveal where the leverage lies","level":2},{"type":"paragraph","text":"Semiconductors are not a single product. A modern chip supply chain depends on design software, manufacturing equipment, materials, specialist talent and factories capable of producing at demanding levels of precision. A country may be strong in some links yet exposed in others."},{"type":"paragraph","text":"U.S. rules make that exposure concrete. A 2022 U.S. Commerce Department regulation introduced controls on certain advanced-computing chips and semiconductor manufacturing items, alongside restrictions connected to supercomputer and chip-production end uses in China. It is a legal control regime, not a blanket ban on every chip or every technology trade with China. [3]"},{"type":"paragraph","text":"RAND’s 2025 analysis of China’s AI industrial policy describes the resulting bind: Chinese firms are developing local chip and software alternatives, but controls on advanced computing chips and manufacturing equipment constrain access to computing power and the ability to manufacture leading-edge processors. The report also warns that controls are unlikely to stop China’s AI progress altogether. State support, private-sector competition and applications across industry can sustain progress even when a particular input is scarce. [4]"},{"type":"paragraph","text":"This is why the contest concerns the whole stack, not just the fastest processor. Domestic AI accelerators, software platforms, research funding, data centers and industrial customers can create a usable ecosystem before every component matches the world’s best. Conversely, a highly capable chip may be less valuable if the tools to design, manufacture or deploy it are missing."},{"type":"paragraph","text":"China’s policy is therefore partly defensive: reduce the risk that a foreign government’s licensing decision can interrupt critical development. It is also a bet that a large home market and state-backed coordination can help local alternatives improve through use. Neither outcome is guaranteed. State investment can accelerate learning, but the U.S. commission’s review also records missed targets and persistent barriers where entrenched incumbents hold specialized expertise and intellectual property. [4] [5]"},{"type":"heading","text":"Rare earths show the other side of the equation","level":2},{"type":"paragraph","text":"In chips, China seeks to catch up in areas where foreign restrictions can bite. In rare earths, China already occupies a much stronger position in processing and downstream production. The International Energy Agency estimates that China accounts for about 91% of global separation and refining for magnet rare earths, and 94% of sintered permanent-magnet production. These materials and magnets feed into motors, vehicles, wind turbines, electronics and other advanced manufacturing. [6]"},{"type":"paragraph","text":"The distinction between mining and processing is decisive. An ore deposit is not a ready-to-use magnet. Processing requires specialized facilities, expertise and time to develop. That concentration means supply disruption can impose costs well beyond the mining sector. In 2025, the IEA reported that export curbs coincided with steeply reduced shipments and disruption for some overseas manufacturers; rare-earth prices in importing markets also diverged sharply from prices in China. [6]"},{"type":"paragraph","text":"China’s Ministry of Commerce says its controls are a lawful national-security measure, not an export ban, and that eligible civilian applications can be licensed. That is Beijing’s stated position. The uncertainty for foreign buyers is whether access will be timely, transparent and predictable in practice. [10]"},{"type":"paragraph","text":"The important timeline is often missed. China’s April 2025 controls on seven heavy rare earths and related products took effect immediately. A second, broader wave announced in October—including five additional elements and wider requirements—was suspended until November 10, 2026. As of September 26, 2026, the October expansion remains suspended, but the April controls have not been erased. Reuters reported this month that some Chinese suppliers were still declining U.S.-bound shipments despite licences, while companies in several countries faced delays. These reported cases do not establish a blanket cutoff; they do show that a licence is not always the same as dependable access. [7] [8] [9]"},{"type":"paragraph","text":"So far, China’s strongest leverage comes less from a total prohibition than from the possibility of delay, uncertainty and selective permission in a concentrated market. This can prompt buyers to redesign products, stock inventory or invest in alternatives. It can also motivate customers to spend years building supply chains elsewhere—gradually weakening the leverage that created the incentive in the first place."}]'::jsonb, 'MONEY', 7, 'published', 'Why China Wants Control of More of the Technology Supply Chain | Omniv', 'When China tightened controls on rare earth exports in April 2025, the consequences did not stay inside China. Automakers and other manufacturers abroad scrambled to secure magnets, and some production lines faced shortages. The episode exp…', 'https://omniv.media/p/08-china-supply-chain', '[{"name":"english.gov.cn","title":"Chinese sci-tech minister outlines innovation plans for 2026-2030 period","url":"https://english.www.gov.cn/news/202510/24/content_WS68fb6f9bc6d00ca5f9a07016.html"},{"name":"reuters.com","title":"China''s new five-year plan calls for AI throughout its economy, tech breakthroughs","url":"https://www.reuters.com/world/asia-pacific/china-vows-accelerate-technological-self-reliance-ai-push-2026-03-05/"},{"name":"federalregister.gov","title":"Implementation of Additional Export Controls: Certain Advanced Computing and Semiconductor Manufacturing Items","url":"https://www.federalregister.gov/documents/2022/10/13/2022-21658/implementation-of-additional-export-controls-certain-advanced-computing-and-semiconductor"},{"name":"rand.org","title":"Full Stack: China''s Evolving Industrial Policy for AI","url":"https://www.rand.org/pubs/perspectives/PEA4012-1.html"},{"name":"uscc.gov","title":"Made in China 2025: Evaluating China’s Performance","url":"https://www.uscc.gov/research/made-china-2025-evaluating-chinas-performance"},{"name":"iea.org","title":"With new export controls on critical minerals, supply concentration risks become reality","url":"https://www.iea.org/commentaries/with-new-export-controls-on-critical-minerals-supply-concentration-risks-become-reality"},{"name":"english.mofcom.gov.cn","title":"Announcement No.18 of 2025 on export controls on some medium and heavy rare earth related items","url":"https://english.mofcom.gov.cn/Policies/AnnouncementsOrders/art/2025/art_0dd87cbee7b045bf93fabe6ab2faceee.html"},{"name":"europarl.europa.eu","title":"China''s rare-earth export restrictions","url":"https://www.europarl.europa.eu/RegData/etudes/ATAG/2025/779220/EPRS_ATA%282025%29779220_EN.pdf"},{"name":"reuters.com","title":"China rare earth firms halt some US shipments over geopolitical worries, sources say","url":"https://www.reuters.com/business/aerospace-defense/china-rare-earth-firms-halt-some-us-shipments-over-geopolitical-worries-sources-2026-09-04/"},{"name":"english.mofcom.gov.cn","title":"MOFCOM Spokesperson’s Remarks on China’s Recent Economic and Trade Policies and Measures","url":"https://english.mofcom.gov.cn/News/SpokesmansRemarks/art/2025/art_c202dcc0433d476db52b1e7f7fe53926.html"}]'::jsonb, 'For companies, “China exposure” is not a useful enough answer. The consequential question is which link is exposed: a mineral, a component, a manufacturing tool, a software platform, or a licence. A product assembled outside China may still depend on Chinese processing or materials; a Chinese factory may depend on imported equipment or software. Mapping the immediate supplier alone can miss the constraint several steps upstream. For governments, resilience is not the same thing as national autarky. Duplicating every mine, refinery, chip plant and toolmaker inside one border would be costly and slow. The more practical choices are targeted: identify chokepoints, build alternative capacity where it is feasible, coordinate with trusted trading partners, and keep enough inventory or design flexibility to bridge disruptions. Diversification is a long project, not an emergency purchase. For investors and customers, the key is to separate announced ambition from delivered capacity. Policy plans and public funding can signal where capital may flow. They do not, by themselves, prove that a supplier can meet global standards, achieve competitive yields or operate profitably without continuing support. China’s gains are real; so are the gaps identified in areas such as advanced chips. [4] [5]', 'If China succeeds in making itself less dependent on foreign technology, will the rest of the world become less dependent on China? Not automatically. A second source for a material can take years to permit and scale. Processing capacity is harder to reproduce than a list of alternative suppliers suggests. And even when new capacity comes online, it may be more expensive or reliant on Chinese technology, equipment or feedstock. The same industrial concentration that gives Beijing leverage can also make diversification commercially unattractive until a disruption forces the calculation. There is a further irony: controls intended to preserve strategic advantage can make global firms and governments more determined to leave a concentrated system. China’s leverage is strongest while customers have few practical alternatives. The more that leverage is used, the greater the incentive to build them. Where the balance settles—in open trade with narrower dependencies, or in rival technology blocs—is still uncertain. [6] [9]', '[{"type":"project","slug":"china","label":"China"},{"type":"project","slug":"united-states","label":"United States"},{"type":"project","slug":"taiwan","label":"Taiwan"},{"type":"project","slug":"japan","label":"Japan"},{"type":"project","slug":"semiconductors","label":"Semiconductors"},{"type":"project","slug":"artificial-intelligence","label":"Artificial Intelligence"},{"type":"project","slug":"rare-earths","label":"Rare Earths"},{"type":"project","slug":"global-supply-chains","label":"Global Supply Chains"}]'::jsonb, '{}'::text[], ARRAY['money', 'china', 'united states', 'taiwan', 'japan', 'semiconductors'], '7 min read', 90, '2026-09-23T08:00:00Z') on conflict (slug) do update set publisher_id=excluded.publisher_id, publisher_name=excluded.publisher_name, title=excluded.title, summary=excluded.summary, subtitle=excluded.subtitle, excerpt=excluded.excerpt, content=excluded.content, category_id=excluded.category_id, reading_time=excluded.reading_time, status='published', seo_title=excluded.seo_title, seo_description=excluded.seo_description, canonical_url=excluded.canonical_url, sources=excluded.sources, what_this_means=excluded.what_this_means, question_nobody_asks=excluded.question_nobody_asks, entity_refs=excluded.entity_refs, related_publication_ids=excluded.related_publication_ids, tags=excluded.tags, meta=excluded.meta, heat=excluded.heat, published_at=excluded.published_at, updated_at=now();
insert into public.discovery_publications (publisher_id, publisher_name, type, slug, title, summary, body, subtitle, excerpt, content, category_id, reading_time, status, seo_title, seo_description, canonical_url, sources, what_this_means, question_nobody_asks, entity_refs, related_publication_ids, tags, meta, heat, published_at) values ((select id from public.discovery_entities where type='company' and slug='omniv'), 'Omniv', 'article', '09-two-tech-systems', 'What Happens If the World Splits Into Two Technology Systems?', 'A phone, car or AI service can look like one product. Underneath it may depend on chip designs from one country, manufacturing tools from another, fabrication concentrated in Taiwan, minerals processed elsewhere, and software distributed ar…', '', 'From chips and cloud computing to AI rules and critical minerals, countries are trying to reduce exposure to rivals. The likely result is not two sealed-off internets—but a more expensive, less predictable technology map with narrow bridges between competing systems.', 'A phone, car or AI service can look like one product. Underneath it may depend on chip designs from one country, manufacturing tools from another, fabrication concentrated in Taiwan, minerals processed elsewhere, and software distributed ar…', '[{"type":"paragraph","text":"A phone, car or AI service can look like one product. Underneath it may depend on chip designs from one country, manufacturing tools from another, fabrication concentrated in Taiwan, minerals processed elsewhere, and software distributed around the world. The politics of technology now reach into all those links."},{"type":"paragraph","text":"The phrase “two technology systems” suggests a clean division: one led by the United States and its partners, another by China. That is a useful shorthand for strategic competition, not a literal description of how technology works today. The evidence shows selective controls, subsidies, and efforts to build alternatives—not a completed global divorce. A split, if it deepens, would be uneven: chips and AI infrastructure may separate faster than ordinary consumer goods or the basic protocols that let networks communicate."},{"type":"paragraph","text":"The question is not simply who would win. It is what changes when access to technology depends increasingly on where it was designed, made, hosted, or governed."},{"type":"heading","text":"The split is already visible—but not complete","level":2},{"type":"paragraph","text":"The clearest dividing line runs through advanced semiconductors. In December 2024, the U.S. Commerce Department announced controls covering 24 types of chipmaking equipment, three categories of software tools, high-bandwidth memory, and 140 additions to its Entity List. Washington said the measures were intended to restrict China’s ability to produce advanced chips for military applications. That is the government’s stated rationale; the announcement itself does not establish how effective the controls will be over time. [1]"},{"type":"paragraph","text":"China has also used export controls. A Ministry of Commerce notice issued the next day prohibited exports of covered dual-use items to U.S. military users or for military uses, and said exports of gallium, germanium, antimony and superhard materials to the United States would, in principle, not be permitted. It also tightened checks on graphite exports. This is a specific measure, not evidence that China stopped exporting all these materials to every destination. [2]"},{"type":"paragraph","text":"Each move illustrates a wider shift: governments are treating some commercial technologies and inputs as matters of national security. That does not mean all trade is being cut off. A Congressional Research Service review in 2025 noted that U.S. controls had restricted some advanced technologies while other parts of the semiconductor supply chain remained open to China. [3]"},{"type":"paragraph","text":"The result is a patchwork of restrictions, licences, subsidies and carve-outs. A company may still sell in a market, but face new conditions on which chips it can supply, what equipment it can maintain, or where it can expand a factory. Legal boundaries can change faster than physical supply chains can be rebuilt."},{"type":"heading","text":"Why chips are the pressure point","level":2},{"type":"paragraph","text":"A chip is not a single-country product. Design software, intellectual property, manufacturing equipment, specialty materials, fabrication, packaging and testing are distinct stages. The OECD’s 2025 mapping of the semiconductor value chain describes it as globally distributed and tightly interconnected, with critical inputs concentrated in particular regions and economies specialized in different segments. It warns that disruption in a leading economy can cascade into shortages for downstream industries. [4]"},{"type":"paragraph","text":"That concentration is especially consequential for Taiwan. TSMC’s 2024 annual report lists its largest set of fabrication facilities in Taiwan, alongside operations in China, Japan and the United States. Its report also describes surging AI demand and record revenues in 2024. These are company-reported facts; they show both how central one manufacturer is to global production and how much activity is already distributed across borders. They do not mean overseas sites can immediately duplicate every capability at home. [5]"},{"type":"paragraph","text":"Governments are trying to reduce risks by encouraging more local production. The United States’ CHIPS Act, for example, provides incentives for domestic semiconductor investment. Its final security rules also restrict recipients from materially expanding advanced-chip manufacturing in countries of concern for ten years, subject to the rule’s scope and exceptions. Such policies can add capacity and provide insurance against disruption. They also tie investment decisions more closely to political blocs. [6]"},{"type":"paragraph","text":"But building a fab is not the same as replacing a whole ecosystem. It takes capital, specialized workers, reliable electricity and water, suppliers, customers, and years of process learning. OECD analysis says diversification requires substantial investment, skilled labor and infrastructure. **Analysis:** if governments pursue resilience by duplicating every stage inside friendly borders, consumers and firms may pay for redundant capacity while still relying on external partners for some inputs. [4]"},{"type":"heading","text":"What two systems would mean for business and people","level":2},{"type":"paragraph","text":"For companies, the immediate cost is complexity. A product sold worldwide might need separate chip configurations, cloud hosting, software updates, compliance reviews, or supplier networks depending on destination. If rules diverge, businesses could need separate certifications and technical teams. Smaller companies, which cannot afford parallel operations as easily as global giants, may find some markets harder to enter. These are plausible effects of regulatory and technical divergence, not guaranteed outcomes for every firm."},{"type":"paragraph","text":"For consumers, the consequences may show up as higher prices, fewer choices, delayed features or inconsistent services across borders. A firm that cannot legally provide the same software, AI model or cloud service everywhere may offer a reduced version—or withdraw. Restrictions can also limit access to useful technology and research. At the same time, public support for domestic capacity could create jobs and make some supplies less vulnerable to a crisis. Security and efficiency can pull in opposite directions."},{"type":"paragraph","text":"The costs are difficult to forecast. The IMF has summarized estimates that greater international trade restrictions could reduce long-run global output by as much as 7 percent, or about $7.4 trillion in the dollars used for its calculation. That is a scenario-dependent estimate of broad fragmentation, not a prediction that a technology split alone will cause that loss. IMF researchers identify trade, capital flows, technology diffusion and public goods as channels through which fragmentation could impose costs. [7]"},{"type":"paragraph","text":"Trade data also counsel against treating “two blocs” as a settled fact. A WTO working paper analyzing goods trade through February 2024 found early signs of friend-shoring after Russia’s invasion of Ukraine, but no increased regionalization after the pandemic or the invasion. It reported that trade between hypothetical East and West blocs grew more slowly than trade within them, while also distinguishing U.S.–China decoupling from wider geopolitical alignment. The authors call this work in progress, not an official WTO position. [8]"},{"type":"heading","text":"Not just chips: rules, data and materials","level":2},{"type":"paragraph","text":"Technology systems are made of rules as well as machines. The European Union’s AI Act sets a risk-based legal framework for AI in the EU, with obligations taking effect in stages. The OECD’s AI Recommendation, amended in 2024, offers a common intergovernmental set of principles, including human rights, transparency, safety and accountability. These examples show that different jurisdictions can regulate differently while still drawing on shared vocabulary. A different rulebook does not automatically mean incompatible software or a separate internet. [9] [10]"},{"type":"paragraph","text":"The United Nations’ 2024 Global Digital Compact calls for an open, global, interoperable and reliable internet, while supporting international cooperation on data governance and AI. Its existence is evidence of an effort to preserve common ground, not proof that governments will resolve disagreements over surveillance, privacy, censorship, security or data access. [11]"},{"type":"paragraph","text":"Critical materials add another point of leverage. OECD analysis of raw-material supply chains says the three largest producing countries accounted for 90 percent of rare-earth-element production in 2023. Extraction and processing are concentrated for geological and industrial reasons; restrictions can ripple through international markets. That concentration creates exposure in both directions: countries that rely on foreign processing face supply risks, while producers can face lost revenue and customers may seek alternatives. [12]"}]'::jsonb, 'EXPLAINED', 8, 'published', 'What Happens If the World Splits Into Two Technology Systems? | Omniv', 'A phone, car or AI service can look like one product. Underneath it may depend on chip designs from one country, manufacturing tools from another, fabrication concentrated in Taiwan, minerals processed elsewhere, and software distributed ar…', 'https://omniv.media/p/09-two-tech-systems', '[{"name":"bis.gov","title":"Commerce Strengthens Export Controls to Restrict China’s Capability to Produce Advanced Semiconductors for Military Applications","url":"https://www.bis.gov/press-release/commerce-strengthens-export-controls-restrict-chinas-capability-produce-advanced-semiconductors-military"},{"name":"cset.georgetown.edu","title":"China Ministry of Commerce Notice 2024 No. 46: Strengthening Controls on Exports of Relevant Dual-Use Items to the United States (CSET translation)","url":"https://cset.georgetown.edu/publication/china-rare-earth-export-ban/"},{"name":"congress.gov","title":"U.S. Export Controls and China: Advanced Semiconductors","url":"https://www.congress.gov/crs-product/R48642"},{"name":"oecd.org","title":"Mapping the Semiconductor Value Chain: Working towards Identifying Dependencies and Vulnerabilities","url":"https://www.oecd.org/en/publications/mapping-the-semiconductor-value-chain_4154cdbf-en.html"},{"name":"investor.tsmc.com","title":"TSMC 2024 Annual Report","url":"https://investor.tsmc.com/static/annualReports/2024/english/index.html"},{"name":"nist.gov","title":"Final National Security Guardrails for CHIPS for America Incentives Program","url":"https://www.nist.gov/news-events/news/2023/09/biden-harris-administration-announces-final-national-security-guardrails"},{"name":"imf.org","title":"The High Cost of Global Economic Fragmentation","url":"https://www.imf.org/en/blogs/articles/2023/08/28/the-high-cost-of-global-economic-fragmentation"},{"name":"wto.org","title":"Is the Global Economy Fragmenting?","url":"https://www.wto.org/english/res_e/reser_e/ersd202310_e.htm"},{"name":"digital-strategy.ec.europa.eu","title":"AI Act: Regulatory Framework for Artificial Intelligence","url":"https://digital-strategy.ec.europa.eu/en/policies/regulatory-framework-ai"},{"name":"legalinstruments.oecd.org","title":"OECD Recommendation of the Council on Artificial Intelligence","url":"https://legalinstruments.oecd.org/en/instruments/oecd-legal-0449"},{"name":"un.org","title":"Annex I: Global Digital Compact","url":"https://www.un.org/pact-for-the-future/en/annex-i-global-digital-compact"},{"name":"oecd.org","title":"Economic Security in a Changing World: Special Focus on Critical Raw Materials Supply Chains","url":"https://www.oecd.org/en/publications/2025/09/economic-security-in-a-changing-world_78f3b129/full-report/special-focus-critical-raw-materials-supply-chains_daf99c07.html"}]'::jsonb, 'A divided technology landscape would probably be neither a single “internet shutdown” nor two fully self-sufficient industrial empires. It would be a graduated separation. Some sensitive chips, manufacturing tools, investment and data services could be tightly controlled. Elsewhere, trade and research could continue under new conditions. Shared networks and standards might persist even as countries disagree about who can use particular technologies and under what rules. For businesses, the useful question is not only “Which side are we on?” It is: which suppliers, facilities, software dependencies and customers are vulnerable to a change in policy—and how quickly could they be replaced? Resilience is not achieved just by announcing a new factory. It depends on the surrounding network of talent, infrastructure and trusted suppliers. For the public, the trade-off is between safeguards and access. Controls may reduce specific security risks, but they can also close markets, raise costs, slow diffusion of beneficial tools, and encourage retaliation. Industrial subsidies can build capacity, but they cannot guarantee that it will be economical or available when a crisis hits. The outcome depends on policy choices, company decisions and whether governments preserve practical cooperation in less sensitive areas.', 'If nations can make their own chips, clouds and AI rules, who pays to keep them compatible? Interoperability is easy to take for granted. It requires engineers to agree on technical standards, companies to maintain interfaces, and regulators to allow cross-border services where safeguards are met. The UN’s compact and the OECD’s AI principles point to shared frameworks, but they do not settle the harder disputes. When national security, commercial advantage and public rights collide, a technically possible bridge may still be politically blocked. That is why “two systems” is not only a story about competing inventions. It is also a contest over whether differences can coexist without cutting off useful exchange—and whether states will invest in the bridges as deliberately as they invest in the walls.', '[{"type":"project","slug":"united-states","label":"United States"},{"type":"project","slug":"china","label":"China"},{"type":"project","slug":"taiwan","label":"Taiwan"},{"type":"company","slug":"tsmc","label":"TSMC"},{"type":"project","slug":"semiconductors","label":"Semiconductors"},{"type":"project","slug":"artificial-intelligence","label":"Artificial Intelligence"},{"type":"project","slug":"rare-earths","label":"Rare Earths"},{"type":"project","slug":"global-supply-chains","label":"Global Supply Chains"}]'::jsonb, '{}'::text[], ARRAY['explained', 'united states', 'china', 'taiwan', 'tsmc', 'semiconductors'], '8 min read', 90, '2026-09-22T09:00:00Z') on conflict (slug) do update set publisher_id=excluded.publisher_id, publisher_name=excluded.publisher_name, title=excluded.title, summary=excluded.summary, subtitle=excluded.subtitle, excerpt=excluded.excerpt, content=excluded.content, category_id=excluded.category_id, reading_time=excluded.reading_time, status='published', seo_title=excluded.seo_title, seo_description=excluded.seo_description, canonical_url=excluded.canonical_url, sources=excluded.sources, what_this_means=excluded.what_this_means, question_nobody_asks=excluded.question_nobody_asks, entity_refs=excluded.entity_refs, related_publication_ids=excluded.related_publication_ids, tags=excluded.tags, meta=excluded.meta, heat=excluded.heat, published_at=excluded.published_at, updated_at=now();
